### Description of the Terraform Program

This Terraform program configures an AWS environment with two separate Route 53 zones: one for internal users and another for external users. The internal users are routed to a private RDS instance, while external users are routed to a publicly accessible RDS instance. The program sets up a VPC with both private and public subnets, creates a DB subnet group, and defines security groups for both RDS instances. Finally, it creates Route 53 records to map the DNS names to the respective RDS endpoints.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "private_subnet" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "public_subnet" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  map_public_ip_on_launch = true
}

resource "aws_db_subnet_group" "main_db_subnet_group" {
  name       = "main"
  subnet_ids = [aws_subnet.private_subnet.id, aws_subnet.public_subnet.id]
}

resource "aws_security_group" "internal_sg" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "internal_sg"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }
}

resource "aws_security_group" "public_sg" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "public_sg"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "internal_rds" {
  identifier         = "internal"
  instance_class     = "db.t3.micro"
  engine             = "mysql"
  engine_version     = "8.0"
  allocated_storage  = 20
  username           = "admin"
  password           = "password"
  db_subnet_group_name = aws_db_subnet_group.main_db_subnet_group.name
  vpc_security_group_ids = [aws_security_group.internal_sg.id]
  publicly_accessible = false
}

resource "aws_db_instance" "public_rds" {
  identifier         = "public"
  instance_class     = "db.t3.micro"
  engine             = "mysql"
  engine_version     = "8.0"
  allocated_storage  = 20
  username           = "admin"
  password           = "password"
  db_subnet_group_name = aws_db_subnet_group.main_db_subnet_group.name
  vpc_security_group_ids = [aws_security_group.public_sg.id]
  publicly_accessible = true
}

resource "aws_route53_zone" "private_zone" {
  name = "private.example.com"
}

resource "aws_route53_zone" "public_zone" {
  name = "public.example.com"
}

resource "aws_route53_record" "private_db_record" {
  zone_id = aws_route53_zone.private_zone.zone_id
  name    = "db"
  type    = "A"
  ttl     = 300
  records = [aws_db_instance.internal_rds.address]
}

resource "aws_route53_record" "public_db_record" {
  zone_id = aws_route53_zone.public_zone.zone_id
  name    = "db"
  type    = "A"
  ttl     = 300
  records = [aws_db_instance.public_rds.address]
}
```

This configuration ensures that internal users are routed to the private RDS instance via the private Route 53 zone, while external users are routed to the public RDS instance via the public Route 53 zone. The security groups are configured to allow access to the RDS instances based on their respective requirements.

