### Description
This Terraform configuration sets up an Elastic Beanstalk environment with autoscaling settings using thresholds and CPU utilization. It includes the creation of an IAM role (`eb_ec2_role`), an instance profile (`eb_ec2_profile`), and an Elastic Beanstalk application (`my_api_app`). The environment is configured to automatically scale based on CPU utilization.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for EC2 instances in Elastic Beanstalk
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkWebTier",
    "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkWorkerTier",
    "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
  ]
}

# IAM Instance Profile associated with the IAM role
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "my_api_app" {
  name        = "my_api_app"
  description = "Elastic Beanstalk Application for my API"
}

# Elastic Beanstalk Environment with autoscaling settings
resource "aws_elastic_beanstalk_environment" "my_api_env" {
  name                = "my_api_env"
  application         = aws_elastic_beanstalk_application.my_api_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.3.1 running Python 3.8"

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "4"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "MeasureName"
    value     = "CPUUtilization"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "Statistic"
    value     = "SampleCount"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "Unit"
    value     = "Percent"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "Period"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "EvaluationPeriods"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "LowerThreshold"
    value     = "20"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "BreachDuration"
    value     = "5"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "Operator"
    value     = "LessThanThreshold"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "AdjustmentType"
    value     = "ChangeInCapacity"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "ScalingAdjustment"
    value     = "-1"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "UpperThreshold"
    value     = "80"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "AlarmName"
    value     = "HighCPUUtilization"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "Namespace"
    value     = "AWS/ElasticBeanstalk"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "Dimensions"
    value     = "AutoScalingGroupName"
  }
}
```

This configuration sets up the necessary resources and configurations to create an Elastic Beanstalk environment with autoscaling based on CPU utilization. The IAM role and instance profile are created to allow the EC2 instances to operate within the Elastic Beanstalk environment. The autoscaling settings are defined using the `setting` blocks within the Elastic Beanstalk environment resource.

