```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for the web application
resource "aws_iam_role" "web_app_role" {
  name = "web-app-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for the web application
resource "aws_iam_policy" "web_app_policy" {
  name        = "web-app-policy"
  description = "Policy for the web application"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:*",
          "cloudwatch:*",
          "s3:*"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "attach_web_app_policy" {
  policy_arn = aws_iam_policy.web_app_policy.arn
  role       = aws_iam_role.web_app_role.name
}

# VPC for the web application
resource "aws_vpc" "main_vpc" {
  cidr_block = "10.0.0.0/16"
}

# Internet Gateway for the VPC
resource "aws_internet_gateway" "main_igw" {
  vpc_id = aws_vpc.main_vpc.id
}

# Public Subnet 1 for the VPC
resource "aws_subnet" "public_subnet_1" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  map_public_ip_on_launch = true
}

# Public Subnet 2 for the VPC
resource "aws_subnet" "public_subnet_2" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  map_public_ip_on_launch = true
}

# Route Table for public subnets
resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.main_vpc.id
}

# Route to internet gateway
resource "aws_route" "internet_gateway_route" {
  route_table_id         = aws_route_table.public_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main_igw.id
}

# Associate public subnet 1 with route table
resource "aws_route_table_association" "public_subnet_1_route_table_assoc" {
  subnet_id      = aws_subnet.public_subnet_1.id
  route_table_id = aws_route_table.public_route_table.id
}

# Associate public subnet 2 with route table
resource "aws_route_table_association" "public_subnet_2_route_table_assoc" {
  subnet_id      = aws_subnet.public_subnet_2.id
  route_table_id = aws_route_table.public_route_table.id
}

# RDS instance for the web application
resource "aws_db_instance" "web_app_rds" {
  identifier              = "web-app-rds"
  instance_class          = "db.t3.micro"
  allocated_storage       = 20
  engine                  = "mysql"
  engine_version          = "8.0"
  username                = "admin"
  password                = "password"
  skip_final_snapshot     = true
  publicly_accessible     = true
  db_subnet_group_name    = aws_db_subnet_group.web_app_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.web_app_sg.id]
}

# DB Subnet Group for RDS
resource "aws_db_subnet_group" "web_app_subnet_group" {
  name       = "web-app-subnet-group"
  subnet_ids = [aws_subnet.public_subnet_1.id, aws_subnet.public_subnet_2.id]
}

# Security Group for RDS
resource "aws_security_group" "web_app_sg" {
  name        = "web-app-sg"
  description = "Security group for the web application RDS"
  vpc_id      = aws_vpc.main_vpc.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "web_app_eb_app" {
  name        = "web-app-eb-app"
  description = "Elastic Beanstalk application for the web application"
}

# Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "web_app_eb_env" {
  name                = "web-app-eb-env"
  application         = aws_elastic_beanstalk_application.web_app_eb_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.3.1 running Python 3.8"
  version_label       = "v1"

  setting {
    namespace = "aws:elasticbeanstalk:container:python:options"
    name      = "WSGIPath"
    value     = "application.py"
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBUser"
    value     = aws_db_instance.web_app_rds.username
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBPassword"
    value     = aws_db_instance.web_app_rds.password
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBName"
    value     = "mydatabase"
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBEngine"
    value     = aws_db_instance.web_app_rds.engine
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBInstanceClass"
    value     = aws_db_instance.web_app_rds.instance_class
  }
}
```

