Below is the complete Terraform HCL program that configures an AWS VPC with an internet gateway, two public subnets, a security group, and a route table associated with the public subnets. It also connects these resources to two Elastic Beanstalk environments, which are linked to a shared RDS database.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "eb_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "eb_vpc"
  }
}

resource "aws_internet_gateway" "eb_internet_gateway" {
  vpc_id = aws_vpc.eb_vpc.id
  tags = {
    Name = "eb_internet_gateway"
  }
}

resource "aws_subnet" "eb_subnet_public_1" {
  vpc_id            = aws_vpc.eb_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  map_public_ip_on_launch = true
  tags = {
    Name = "eb_subnet_public_1"
  }
}

resource "aws_subnet" "eb_subnet_public_2" {
  vpc_id            = aws_vpc.eb_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  map_public_ip_on_launch = true
  tags = {
    Name = "eb_subnet_public_2"
  }
}

resource "aws_security_group" "eb_env_sg" {
  vpc_id = aws_vpc.eb_vpc.id
  name   = "eb_env_sg"
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "eb_env_sg"
  }
}

resource "aws_route_table" "eb_route_table" {
  vpc_id = aws_vpc.eb_vpc.id
  tags = {
    Name = "eb_route_table"
  }
}

resource "aws_route" "eb_route_to_internet" {
