The Terraform program below configures AWS resources to manage a domain and directs traffic to an Elastic Beanstalk environment that has a connected RDS database. The environment is named "myenv", the instance profile is "eb_ec2_profile1", and the database is named "myapp_db". The program includes the necessary IAM roles, RDS instance, Elastic Beanstalk application and environment, and Route 53 resources.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "eb_ec2_profile1" {
  name = "eb_ec2_profile1"
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_db_instance" "myapp_db" {
  identifier           = "myapp-db"
  instance_class       = "db.t3.micro"
  engine               = "mysql"
  engine_version       = "8.0"
  username             = "admin"
  password             = "password"
  allocated_storage    = 20
  skip_final_snapshot  = true
  vpc_security_group_ids = ["sg-0123456789abcdef0"]
  db_subnet_group_name = "myapp-subnet-group"
}

resource "aws_elastic_beanstalk_application" "myapp" {
  name        = "myapp"
  description = "My Elastic Beanstalk Application"
}

resource "aws_elastic_beanstalk_environment" "myenv" {
  name                = "myenv"
  application         = aws_elastic_beanstalk_application.myapp.name
  solution_stack_name = "64bit Amazon Linux 2 v3.3.1 running Python 3.8"
  instance_profile    = aws_iam_instance_profile.eb_ec2_profile1.name

  setting {
    namespace = "aws:elasticbeanstalk:container:python"
    name      = "WSGIPath"
    value     = "myapp.wsgi"
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBUser"
    value     = aws_db_instance.myapp_db.username
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBPassword"
    value     = aws_db_instance.myapp_db.password
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBName"
    value     = "myapp_db"
  }
}

resource "aws_route53_zone" "mydomain_zone" {
  name = "example.com"
}

resource "aws_route53_record" "mydomain_record" {
  zone_id = aws_route53_zone.mydomain_zone.zone_id
  name    = "www.example.com"
  type    = "A"
  ttl     = 300

  alias {
    name                   = aws_elastic_beanstalk_environment.myenv.endpoint_url
    zone_id                = aws_route53_zone.mydomain_zone.zone_id
    evaluate_target_health = true
  }
}
