### Description
The Terraform program defines a blue/green deployment setup using Route 53 resources to direct traffic to two separate environments connected to a shared RDS database. It includes IAM roles and policies, a shared RDS database, a Route 53 hosted zone, and DNS records with health checks and failover routing policies. The instance profile is named "eb_ec2_profile", the database is named "myapp_db", and the environments are named "blue" and "green".

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_db_instance" "myapp_db" {
  identifier         = "myapp_db"
  instance_class     = "db.t3.micro"
  engine             = "mysql"
  engine_version     = "8.0"
  username           = "admin"
  password           = "password"
  allocated_storage  = 20
  skip_final_snapshot = true
}

resource "aws_route53_zone" "myapp_zone" {
  name = "myapp.example.com"
}

resource "aws_route53_record" "blue_record" {
  zone_id = aws_route53_zone.myapp_zone.zone_id
  name    = "blue.myapp.example.com"
  type    = "A"
  ttl     = 300
  records = ["192.168.1.1"]
}

resource "aws_route53_record" "green_record" {
  zone_id = aws_route53_zone.myapp_zone.zone_id
  name    = "green.myapp.example.com"
  type    = "A"
  ttl     = 300
  records = ["192.168.1.2"]
}

resource "aws_route53_health_check" "blue_health_check" {
  type                = "HTTP"
  fqdn                = "blue.myapp.example.com"
  port                = 80
  resource_path       = "/"
  failure_threshold   = 3
  request_interval    = 30
}

resource "aws_route53_health_check" "green_health_check" {
  type                = "HTTP"
  fqdn                = "green.myapp.example.com"
  port                = 80
  resource_path       = "/"
  failure_threshold   = 3
  request_interval    = 30
}

resource "aws_route53_record" "failover_record" {
  zone_id = aws_route53_zone.myapp_zone.zone_id
  name    = "myapp.example.com"
  type    = "A"
  ttl     = 300

  failover_routing_policy {
    type = "PRIMARY"
  }

  health_check_id = aws_route53_health_check.blue_health_check.id

  records = ["192.168.1.1"]

  depends_on = [
    aws_route53_health_check.blue_health_check,
    aws_route53_health_check.green_health_check
  ]
}

resource "aws_route53_record" "failover_record_secondary" {
  zone_id = aws_route53_zone.myapp_zone.zone_id
  name    = "myapp.example.com"
  type    = "A"
  ttl     = 300

  failover_routing_policy {
    type = "SECONDARY"
  }

  health_check_id = aws_route53_health_check.green_health_check.id

  records = ["192.168.1.2"]

  depends_on = [
    aws_route53_health_check.blue_health_check,
    aws_route53_health_check.green_health_check
  ]
}
```

