  acl    = "private"
}

# Random string suffix for S3 bucket name
resource "random_string" "suffix" {
  length  = 8
  special = false
}

# S3 Bucket Lifecycle Configuration
resource "aws_s3_bucket_lifecycle_configuration" "application_versions_bucket_lifecycle" {
  bucket = aws_s3_bucket.application_versions_bucket.id

  rule {
    id     = "expire-old-versions"
    status = "Enabled"

    expiration {
      days = 5
    }
  }
}
```

