### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for CodeBuild
resource "aws_iam_role" "codebuild_example_role" {
  name = "codebuild-example-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for CodeBuild
resource "aws_iam_role_policy" "codebuild_example_policy" {
  role = aws_iam_role.codebuild_example_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "s3:*",
          "ec2:CreateNetworkInterface",
          "ec2:DescribeDhcpOptions",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVpcs",
          "ec2:CreateNetworkInterfacePermission",
          "codeconnections:GetConnectionToken",
          "codeconnections:GetConnection"
        ]
        Resource = "*"
      },
    ]
  })
}

# CodeBuild Project
resource "aws_codebuild_project" "example_codebuild_project" {
  name          = "example-codebuild-project"
  description   = "Example CodeBuild Project"
  service_role  = aws_iam_role.codebuild_example_role.arn
  build_timeout = 60

  artifacts {
    type = "NO_ARTIFACTS"
  }

  cache {
    type     = "S3"
    location = "codebuild-artifacts-bucket"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  source {
    type            = "GITHUB"
    location        = "https://github.com/example/example.git"
    git_clone_depth = 1
  }

  tags = {
    Environment = "Example"
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **IAM Role**: An IAM role named `codebuild-example-role` is created with a trust policy that allows CodeBuild to assume the role.
3. **IAM Policy**: An IAM policy is attached to the role, granting permissions for logging, S3 operations, EC2 network interface management, and CodeBuild connections.
4. **CodeBuild Project**: A CodeBuild project is created with the specified name, description, and service role. It uses a GitHub source, has no artifacts, and uses an S3 cache. The environment is configured for a small Linux container with the specified Docker image.

