data "aws_iam_policy_document" "codebuild_assume_role_policy" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "codebuild_example_role" {
  name               = "codebuild-example-role"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume_role_policy.json
}

data "aws_iam_policy_document" "codebuild_example_policy" {
  statement {
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = ["*"]
  }

  statement {
    effect = "Allow"

    actions = [
      "ec2:CreateNetworkInterface",
      "ec2:DescribeDhcpOptions",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DeleteNetworkInterface",
      "ec2:DescribeSubnets",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeVpcs",
    ]

    resources = ["*"]
  }

  statement {
    effect    = "Allow"
    actions   = ["ec2:CreateNetworkInterfacePermission"]
    resources = ["arn:aws:ec2:us-west-2:123456789012:network-interface/*"]

    condition {
      test     = "StringEquals"
      variable = "ec2:Subnet"

      values = [
        "subnet-12345678",
        "subnet-87654321",
      ]
    }

    condition {
      test     = "StringEquals"
      variable = "ec2:AuthorizedService"
      values   = ["codebuild.amazonaws.com"]
    }
  }

  statement {
    effect  = "Allow"
    actions = ["s3:*"]
    resources = [
      "arn:aws:s3:::example-bucket",
      "arn:aws:s3:::example-bucket/*",
    ]
  }
}

resource "aws_iam_policy" "codebuild_example_policy" {
  name        = "codebuild-example-policy"
  path        = "/"
  description = "Policy for CodeBuild example"
  policy      = data.aws_iam_policy_document.codebuild_example_policy.json
}

resource "aws_iam_role_policy_attachment" "attach_codebuild_policy_to_role" {
  role       = aws_iam_role.codebuild_example_role.name
  policy_arn = aws_iam_policy.codebuild_example_policy.arn
}

resource "aws_codebuild_project" "example_codebuild_project" {
  name         = "example-codebuild-project"
  description  = "Example CodeBuild Project"
  service_role = aws_iam_role.codebuild_example_role.arn

  artifacts {
    type = "S3"
    location = "example-bucket/artifacts"
  }

  secondary_artifacts {
    artifact_identifier = "SecondaryArtifact"
    type              = "S3"
    location          = "example-bucket/secondary-artifacts"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  source {
    type            = "GITHUB"
    location        = "https://github.com/example/repo.git"
    git_clone_depth = 1
  }

  tags = {
    Environment = "Test"
  }
}
```

