Below is a complete Terraform HCL program that creates an AWS Lex bot for booking a trip, including all necessary dependencies such as IAM roles and Lambda functions.

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Lex Bot
resource "aws_iam_role" "lex_bot_role" {
  name = "lex-bot-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lex.amazonaws.com"
        }
      },
    ]
  })
}

# Lambda Function for Lex Bot
resource "aws_lambda_function" "lex_bot_lambda" {
  function_name = "lex-bot-lambda"
  role          = aws_iam_role.lex_bot_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "lambda_function.zip"

  environment {
    variables = {
      LOG_LEVEL = "INFO"
    }
  }
}

# Lex Intent for Booking Trip
resource "aws_lex_intent" "booking_trip_intent" {
  name           = "BookingTrip"
  description    = "Intent to book a trip"
  sample_utterances = [
    "I want to book a trip",
    "Can you help me book a trip",
  ]

  fulfillment_activity {
    type = "ReturnIntent"
  }

  slot {
    name            = "Destination"
    slot_constraint = "Required"
    slot_type       = "AMAZON.City"
    slot_type_version = "$$LATEST"

    value_elicitation_prompt {
      max_attempts = 2

      message {
        content      = "Where would you like to go?"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name            = "StartDate"
    slot_constraint = "Required"
    slot_type       = "AMAZON.Date"
    slot_type_version = "$$LATEST"

    value_elicitation_prompt {
      max_attempts = 2

      message {
        content      = "When would you like to start your trip?"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name            = "EndDate"
    slot_constraint = "Required"
    slot_type       = "AMAZON.Date"
    slot_type_version = "$$LATEST"

    value_elicitation_prompt {
      max_attempts = 2

      message {
        content      = "When would you like to end your trip?"
        content_type = "PlainText"
      }
    }
  }
}

# Lex Bot for Booking Trip
resource "aws_lex_bot" "lex_bot_booking_trip" {
  name             = "BookingTripBot"
  child_directed   = false
  locale           = "en-US"
  process_behavior = "BUILD"
  idle_session_ttl_in_seconds = 300

  abort_statement {
    message {
      content      = "Sorry, I can't assist with that."
      content_type = "PlainText"
    }
  }

  clarification_prompt {
    max_attempts = 2

    message {
      content      = "I didn't understand that. Could you please repeat?"
      content_type = "PlainText"
    }
  }

  intent {
    intent_name    = aws_lex_intent.booking_trip_intent.name
    intent_version = "$$LATEST"
  }
}
```

