### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_lex_intent" "pizza_ordering_intent" {
  name           = "OrderPizza"
  description    = "Intent to order a pizza"
  create_version = false

  sample_utterances = [
    "I want to order a pizza",
    "Can I order a pizza?",
    "I'd like to get a pizza",
  ]

  slot {
    name            = "PizzaSize"
    slot_type       = "AMAZON.NUMBER"
    slot_constraint = "Required"
    description     = "The size of the pizza"

    value_elicitation_prompt {
      max_attempts = 2

      message {
        content      = "What size pizza would you like?"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name            = "Quantity"
    slot_type       = "AMAZON.NUMBER"
    slot_constraint = "Required"
    description     = "The quantity of pizzas"

    value_elicitation_prompt {
      max_attempts = 2

      message {
        content      = "How many pizzas would you like?"
        content_type = "PlainText"
      }
    }
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

resource "aws_lex_bot" "pizza_ordering_bot" {
  name                     = "PizzaOrderingBot"
  child_directed           = false
  locale                   = "en-US"
  nlu_intent_confidence_threshold = 0.5

  abort_statement {
    message {
      content      = "Sorry, I am not able to assist at this time."
      content_type = "PlainText"
    }
  }

  clarification_prompt {
    max_attempts = 2

    message {
      content      = "I didn't understand you, what would you like to do?"
      content_type = "PlainText"
    }
  }

  intent {
    intent_name    = aws_lex_intent.pizza_ordering_intent.name
    intent_version = "$$LATEST"
  }
}
```

