### Description
The Terraform program below creates an AWS Connect bot association. It includes the necessary resources such as an IAM role for the Lex bot, a Lex bot, an AWS Connect instance, and the association between the Connect instance and the Lex bot. The configuration ensures that all required attributes are specified and that there are no unsupported arguments.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for Lex bot
resource "aws_iam_role" "lex_bot_role" {
  name = "lex-bot-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Sid    = ""
        Principal = {
          Service = "lex.amazonaws.com"
        }
      },
    ]
  })
}

# Create a Lex bot
resource "aws_lex_bot" "example" {
  name                = "example-bot"
  child_directed      = false
  process_behavior    = "BUILD"
  idle_session_ttl_in_seconds = 60

  abort_statement {
    message {
      content      = "Sorry, I am not able to assist at this time"
      content_type = "PlainText"
    }
  }

  intent {
    intent_name    = "OrderFlowers"
    intent_version = "1"
  }
}

# Create a Connect instance
resource "aws_connect_instance" "example" {
  identity_management_type = "CONNECT_MANAGED"
  inbound_calls_enabled    = true
  outbound_calls_enabled   = true
  instance_alias           = "example-instance"
}

# Create a Connect bot association
resource "aws_connect_bot_association" "connect_bot_association" {
  instance_id = aws_connect_instance.example.id

  lex_bot {
    name = aws_lex_bot.example.name
  }
}
```

