### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for Kinesis Firehose
resource "aws_iam_role" "firehose_delivery_role" {
  name = "firehose-delivery-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      },
    ]
  })
}

# Create an IAM policy for Kinesis Firehose to access Redshift
resource "aws_iam_policy" "firehose_delivery_policy" {
  name        = "firehose-delivery-policy"
  description = "Policy for Kinesis Firehose to access Redshift"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "redshift:DescribeClusters",
          "redshift:GetClusterCredentials",
          "redshift:CopyFromS3"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = [
          "arn:aws:s3:::firehose-backup-bucket",
          "arn:aws:s3:::firehose-backup-bucket/*"
        ]
      }
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_firehose_policy_to_role" {
  policy_arn = aws_iam_policy.firehose_delivery_policy.arn
  role       = aws_iam_role.firehose_delivery_role.name
}

# Create a Redshift cluster
resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier = "tf-redshift-cluster"
  database_name      = "mydb"
  master_username    = "exampleuser"
  master_password    = "Mustbe8characters"
  node_type          = "dc1.large"
  cluster_type       = "single-node"
}

# Create an S3 bucket for backup
resource "aws_s3_bucket" "backup_bucket" {
  bucket = "firehose-backup-bucket"
}

# Create a Kinesis Firehose Delivery Stream with Redshift destination
resource "aws_kinesis_firehose_delivery_stream" "kinesis_firehose_delivery_stream" {
  name        = "terraform-kinesis-firehose-test-stream"
  destination = "redshift"

  redshift_configuration {
    role_arn           = aws_iam_role.firehose_delivery_role.arn
    cluster_jdbcurl    = "jdbc:redshift://${aws_redshift_cluster.redshift_cluster.endpoint}/${aws_redshift_cluster.redshift_cluster.database_name}"
    username           = "exampleuser"
    password           = "Mustbe8characters"
    data_table_name    = "test-table"
    copy_options       = "delimiter '|'"
    data_table_columns = "test-col"
    s3_backup_mode     = "Enabled"

    s3_configuration {
      role_arn           = aws_iam_role.firehose_delivery_role.arn
      bucket_arn         = aws_s3_bucket.backup_bucket.arn
      buffering_size     = 10
      buffering_interval = 400
      compression_format = "GZIP"
    }

    s3_backup_configuration {
      role_arn           = aws_iam_role.firehose_delivery_role.arn
      bucket_arn         = aws_s3_bucket.backup_bucket.arn
      buffering_size     = 15
      buffering_interval = 300
      compression_format = "GZIP"
    }
  }
}
