        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Kinesis Analytics V2 Application
resource "aws_kinesisanalyticsv2_application" "kinesis_analytics_app" {
  name                  = "kinesis-analytics-app"
  runtime_environment   = "SQL-1_0"
  service_execution_role = aws_iam_role.kinesis_analytics_role.arn

  application_configuration {
    application_code_configuration {
      code_content {
        text_content = "SELECT * FROM source_stream;"
      }
      code_content_type = "PLAINTEXT"
    }

    sql_application_configuration {
      input {
        name_prefix = "SOURCE_STREAM"

        input_schema {
          record_column {
            name     = "column1"
            sql_type = "VARCHAR(16)"
            mapping  = "$.column1"
          }
          record_column {
            name     = "column2"
            sql_type = "BIGINT"
            mapping  = "$.column2"
          }
          record_format {
            record_format_type = "JSON"

            mapping_parameters {
              json_mapping_parameters {
                record_row_path = "$"
              }
            }
          }
        }

        kinesis_streams_input {
          resource_arn = "arn:aws:kinesis:us-west-2:123456789012:stream/source-stream"
        }
      }

      output {
        name = "DESTINATION_OUTPUT"

        destination_schema {
          record_format_type = "JSON"
        }

        kinesis_firehose_output {
          resource_arn = "arn:aws:firehose:us-west-2:123456789012:deliverystream/destination-firehose"
        }
      }
    }
  }

  cloudwatch_logging_options {
    log_stream_arn = "arn:aws:logs:us-west-2:123456789012:log-group:/aws/kinesis-analytics/kinesis-analytics-app:log-stream:example-log-stream"
  }
}
