### Description
This Terraform configuration sets up an Amazon Kendra data source with a proxy configuration. It includes an IAM role and policy necessary for the Kendra data source to operate. The configuration ensures that the Kendra data source can crawl web content using a specified proxy.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "kendra_index_id" {
  description = "The ID of the Kendra index"
  default     = "synthetic-kendra-index-id"
}

variable "kendra_data_source_name" {
  description = "The name of the Kendra data source"
  default     = "kendra-data-source-with-proxy"
}

variable "kendra_data_source_type" {
  description = "The type of the Kendra data source"
  default     = "WEBCRAWLER"
}

resource "aws_iam_role" "kendra_data_source_role" {
  name = "kendra-data-source-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "kendra_data_source_policy" {
  name = "kendra-data-source-policy"
  role = aws_iam_role.kendra_data_source_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          "arn:aws:s3:::your-bucket-name",
          "arn:aws:s3:::your-bucket-name/*"
        ]
      }
    ]
  })
}

resource "aws_kendra_data_source" "kendra_data_source_with_proxy" {
  index_id = var.kendra_index_id
  name     = var.kendra_data_source_name
  type     = var.kendra_data_source_type
  role_arn = aws_iam_role.kendra_data_source_role.arn

  configuration {
    web_crawler_configuration {
      urls {
        seed_url_configuration {
          seed_urls = [
            "https://example.com"
          ]
        }
      }
      proxy_configuration {
        host = "proxy.example.com"
        port = 8080
      }
    }
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **Variables**: Variables are defined for the Kendra index ID, data source name, and type, with default values provided.
- **IAM Role**: An IAM role named `kendra-data-source-role` is created with a trust policy allowing Kendra to assume the role.
- **IAM Role Policy**: A policy is attached to the IAM role allowing access to S3 buckets.
- **Kendra Data Source**: A Kendra data source is configured with a web crawler type, seed URLs, and a proxy configuration. The data source uses the IAM role created earlier.

