### Description
The Terraform program defines an AWS Kendra data source with URL exclusion and inclusion patterns. It includes the necessary IAM role for Kendra to operate and a Kendra index. The Kendra data source is configured to crawl web content based on specified URL patterns.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "kendra_role" {
  name = "kendra-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_kendra_index" "example_index" {
  name        = "example-kendra-index"
  role_arn    = aws_iam_role.kendra_role.arn
  description = "Example Kendra Index"
}

resource "aws_kendra_data_source" "kendra_data_source" {
  index_id = aws_kendra_index.example_index.id
  name     = "example-kendra-data-source"
  type     = "WEBCRAWLER"

  configuration {
    web_crawler_configuration {
      urls {
        seed_url_configuration {
          seed_urls = ["https://example.com"]
        }
      }
      url_exclusion_patterns = ["https://example.com/exclude/*"]
      url_inclusion_patterns = ["https://example.com/include/*"]
    }
  }

  role_arn = aws_iam_role.kendra_role.arn
}
```

This configuration ensures that the Kendra data source has at least one `urls` block, which is required by the Terraform AWS provider schema. The `seed_url_configuration` within the `urls` block specifies the starting URLs for the web crawler.

