LLM Output #0:
### Description
This Terraform configuration creates an Amazon Kendra index with user group resolution enabled. It includes the necessary IAM role and policy to allow Kendra to resolve user groups. The configuration ensures that all required resources and dependencies are properly defined and linked.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# Create an IAM role for Kendra user group resolution
resource "aws_iam_role" "kendra_user_group_resolution_role" {
  name = "kendra-user-group-resolution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for Kendra user group resolution
resource "aws_iam_policy" "kendra_user_group_resolution_policy" {
  name        = "kendra-user-group-resolution-policy"
  description = "Policy for Kendra user group resolution"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kendra:GetGroupMembers",
          "kendra:GetGroups"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_kendra_policy_to_role" {
  role       = aws_iam_role.kendra_user_group_resolution_role.name
  policy_arn = aws_iam_policy.kendra_user_group_resolution_policy.arn
}

# Create the Kendra index with user group resolution configuration
resource "aws_kendra_index" "kendra_index" {
  name     = "example-kendra-index"
  role_arn = aws_iam_role.kendra_user_group_resolution_role.arn

  user_group_resolution_configuration {
    user_group_resolution_mode = "AWS_SSO"
  }
}
```

This configuration sets up an AWS Kendra index with user group resolution enabled using an IAM role and policy. The IAM role allows Kendra to assume the role, and the policy grants the necessary permissions for Kendra to fetch group members and groups. The Kendra index is then created with the specified user group resolution mode.

