### Description
The Terraform program defines an AWS EKS cluster named "example" and sets up an OIDC identity provider for it. The program includes the necessary IAM roles and policies, and ensures that the OIDC provider and identity provider configuration are correctly linked to the EKS cluster. The configuration is deployable with Terraform version ~> 1.9.8 and the AWS provider version ~> 5.75.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "eks_cluster_role" {
  name = "eks-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster_role.name
}

resource "aws_eks_cluster" "example_eks_cluster" {
  name     = "example"
  role_arn = aws_iam_role.eks_cluster_role.arn

  vpc_config {
    subnet_ids = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1", "subnet-0123456789abcdef2"]
  }

  depends_on = [aws_iam_role_policy_attachment.eks_cluster_policy]
}

resource "aws_iam_openid_connect_provider" "oidc_provider" {
  client_id_list = ["sts.amazonaws.com"]
  url            = aws_eks_cluster.example_eks_cluster.identity[0].oidc.issuer

  depends_on = [aws_eks_cluster.example_eks_cluster]
}

resource "aws_eks_identity_provider_config" "eks_oidc_identity_provider_config" {
  cluster_name = aws_eks_cluster.example_eks_cluster.name

  oidc {
    client_id                     = "your-client-id"
    identity_provider_config_name = "example"
    issuer_url                    = aws_eks_cluster.example_eks_cluster.identity[0].oidc.issuer
  }

  depends_on = [aws_iam_openid_connect_provider.oidc_provider]
}
```

