This Terraform script creates an AWS EKS node group named "example" linked to a specific EKS cluster named "example". The node group is configured with scaling parameters and dependencies on IAM role policy attachments to ensure proper permissions management.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for the EKS Node Group
resource "aws_iam_role" "node_group_role" {
  name = "eks-node-group-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

# Attach EKS Worker Node Policy
resource "aws_iam_role_policy_attachment" "eks_worker_node_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.node_group_role.name
}

# Attach EKS CNI Policy
resource "aws_iam_role_policy_attachment" "eks_cni_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSCNIPolicy"
  role       = aws_iam_role.node_group_role.name
}

# Attach EC2 Container Registry Read Only Policy
resource "aws_iam_role_policy_attachment" "ec2_container_registry_read_only_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.node_group_role.name
}

# EKS Node Group
resource "aws_eks_node_group" "example_node_group" {
  cluster_name    = "example"
  node_role_arn   = aws_iam_role.node_group_role.arn
  subnet_ids      = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]
  node_group_name = "example"

  scaling_config {
    desired_size = 1
    max_size     = 2
    min_size     = 1
  }

  update_config {
    max_unavailable = 1
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_worker_node_policy,
    aws_iam_role_policy_attachment.eks_cni_policy,
    aws_iam_role_policy_attachment.ec2_container_registry_read_only_policy
  ]
}
```

