### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

resource "aws_s3_bucket" "bucket_sample" {
  bucket = "sample"
  acl    = "private"
}

resource "aws_s3_bucket_ownership_controls" "bucket_sample_ownership" {
  bucket = aws_s3_bucket.bucket_sample.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_versioning" "bucket_sample_versioning" {
  bucket = aws_s3_bucket.bucket_sample.id

  versioning_configuration {
    status = "Enabled"
  }
}
```

