### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

resource "aws_s3_bucket" "my_unique_bucket" {
  bucket = "my_unique_bucket_name"  # Ensure this name is globally unique
}

resource "aws_s3_bucket_acl" "my_unique_bucket_acl" {
  bucket = aws_s3_bucket.my_unique_bucket.id
  acl    = "private"  # Set the desired ACL, e.g., private, public-read, etc.
}

resource "aws_s3_bucket_policy" "my_unique_bucket_policy" {
  bucket = aws_s3_bucket.my_unique_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = "*"
        Action = "s3:GetObject"
        Resource = "${aws_s3_bucket.my_unique_bucket.arn}/*"
        Condition = {
          StringLike = {
            "aws:Referer" = "http://example.com/*"
          }
        }
      }
    ]
  })
}
