### Description
The Terraform program below defines a Memcached cluster using AWS Elasticache. It includes the creation of a VPC, a subnet, a security group, and three Memcached instances. The security group allows inbound traffic on port 11211, which is the default port for Memcached.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "memcached_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "MemcachedVPC"
  }
}

resource "aws_subnet" "memcached_subnet" {
  vpc_id            = aws_vpc.memcached_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "MemcachedSubnet"
  }
}

resource "aws_security_group" "memcached_sg" {
  vpc_id = aws_vpc.memcached_vpc.id
  name   = "memcached_sg"

  ingress {
    from_port   = 11211
    to_port     = 11211
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "MemcachedSG"
  }
}

resource "aws_elasticache_cluster" "memcached_cluster" {
  cluster_id           = "memcached-cluster"
  engine               = "memcached"
  node_type            = "cache.t3.medium"
  num_cache_nodes      = 3
  parameter_group_name = "default.memcached1.4"
  port                 = 11211
  subnet_group_name    = aws_elasticache_subnet_group.memcached_subnet_group.name
  security_group_ids   = [aws_security_group.memcached_sg.id]

  tags = {
    Name = "MemcachedCluster"
  }
}

resource "aws_elasticache_subnet_group" "memcached_subnet_group" {
  name       = "memcached-subnet-group"
  subnet_ids = [aws_subnet.memcached_subnet.id]

  tags = {
    Name = "MemcachedSubnetGroup"
  }
}
```

This configuration sets up a basic Memcached cluster in AWS using Elasticache. The VPC, subnet, and security group are configured to support the cluster, and the security group allows inbound traffic on port 11211. The `aws_elasticache_cluster` resource creates the Memcached cluster with three nodes.

