### Description
This Terraform configuration sets up a highly available Amazon Redshift cluster across two availability zones (`us-east-1a` and `us-east-1b`). It includes the creation of a VPC, subnets, a security group, an IAM role, and an IAM policy. The Redshift cluster is configured to use these resources to ensure high availability.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create a VPC
resource "aws_vpc" "redshift_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "RedshiftVPC"
  }
}

# Create subnets in us-east-1a and us-east-1b
resource "aws_subnet" "redshift_subnet_a" {
  vpc_id            = aws_vpc.redshift_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
  tags = {
    Name = "RedshiftSubnetA"
  }
}

resource "aws_subnet" "redshift_subnet_b" {
  vpc_id            = aws_vpc.redshift_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"
  tags = {
    Name = "RedshiftSubnetB"
  }
}

# Create a security group for the Redshift cluster
resource "aws_security_group" "redshift_sg" {
  vpc_id = aws_vpc.redshift_vpc.id
  name   = "redshift-sg"
  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "RedshiftSG"
  }
}

# Create an IAM role for the Redshift cluster
resource "aws_iam_role" "redshift_role" {
  name = "redshift-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
  tags = {
    Name = "RedshiftRole"
  }
}

# Create an IAM policy for the Redshift role
resource "aws_iam_policy" "redshift_policy" {
  name        = "redshift-policy"
  description = "Policy for Redshift operations"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:*",
          "ec2:*"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
  tags = {
    Name = "RedshiftPolicy"
  }
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_redshift_policy_to_role" {
  policy_arn = aws_iam_policy.redshift_policy.arn
  role       = aws_iam_role.redshift_role.name
}

# Create a highly available Redshift cluster
resource "aws_redshift_cluster" "high_availability_redshift_cluster" {
  cluster_identifier = "high-availability-redshift-cluster"
  node_type          = "dc2.large"
  cluster_type       = "multi-node"
  database_name      = "mydb"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  number_of_nodes    = 2
  vpc_security_group_ids = [aws_security_group.redshift_sg.id]
  cluster_subnet_group_name = "default"
  iam_roles          = [aws_iam_role.redshift_role.arn]
  publicly_accessible = false
  enhanced_vpc_routing = true
  multi_az           = true
  tags = {
    Name = "HighAvailabilityRedshiftCluster"
  }
}
```

This Terraform configuration ensures that the Redshift cluster is highly available by placing it across two subnets in different availability zones. The IAM role and policy provide the necessary permissions for the cluster to operate effectively.

