### Description
This Terraform configuration creates a 2-node Amazon Redshift cluster and attaches a resource policy to it. The configuration includes the creation of an IAM role and policy necessary for the Redshift cluster to function properly. The Redshift cluster nodes are configured to use the IAM role, and a resource policy is attached to the cluster to control access.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Redshift
resource "aws_iam_role" "redshift_cluster_role" {
  name = "redshift-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Redshift
resource "aws_iam_policy" "redshift_cluster_policy" {
  name        = "redshift-cluster-policy"
  description = "Policy for Redshift cluster"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          "arn:aws:s3:::my-redshift-bucket",
          "arn:aws:s3:::my-redshift-bucket/*"
        ]
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_redshift_policy_to_role" {
  policy_arn = aws_iam_policy.redshift_cluster_policy.arn
  role       = aws_iam_role.redshift_cluster_role.name
}

# First node of the Redshift cluster
resource "aws_redshift_cluster" "redshift_cluster_node_1" {
  cluster_identifier = "redshift-cluster-node-1"
  node_type          = "dc2.large"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  iam_roles          = [aws_iam_role.redshift_cluster_role.arn]
  cluster_type       = "multi-node"
  number_of_nodes    = 2
}

# Second node of the Redshift cluster
resource "aws_redshift_cluster" "redshift_cluster_node_2" {
  cluster_identifier = "redshift-cluster-node-2"
  node_type          = "dc2.large"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  iam_roles          = [aws_iam_role.redshift_cluster_role.arn]
  cluster_type       = "multi-node"
  number_of_nodes    = 2
}

# Resource policy for the Redshift cluster
resource "aws_redshift_resource_policy" "redshift_cluster_resource_policy" {
  resource_arn = aws_redshift_cluster.redshift_cluster_node_1.arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "redshift:*"
        Effect = "Allow"
        Principal = "*"
        Resource = aws_redshift_cluster.redshift_cluster_node_1.arn
      }
    ]
  })
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role**: An IAM role named `redshift-cluster-role` is created with a trust policy allowing Redshift to assume the role.
3. **IAM Policy**: An IAM policy named `redshift-cluster-policy` is created to allow access to an S3 bucket.
4. **Policy Attachment**: The IAM policy is attached to the IAM role.
5. **Redshift Cluster Nodes**: Two Redshift cluster nodes are created with the specified node type, master username, password, and IAM role.
6. **Resource Policy**: A resource policy is attached to the Redshift cluster to control access to the cluster resources.

