      },
    ]
  })
}

# IAM Policy for Lambda
resource "aws_iam_policy" "lambda_policy" {
  name        = "lambda_policy"
  description = "Policy for Lambda to access necessary resources"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Attach the policy to the Lambda execution role
resource "aws_iam_role_policy_attachment" "attach_lambda_policy_to_role" {
  policy_arn = aws_iam_policy.lambda_policy.arn
  role       = aws_iam_role.lambda_execution_role.name
}

# S3 Bucket to store Lambda function code
resource "aws_s3_bucket" "lambda_code_bucket" {
  bucket = "lambda-code-bucket-${random_string.suffix.result}"
  acl    = "private"
}

# Random string suffix for S3 bucket name
resource "random_string" "suffix" {
  length  = 8
  special = false
}

# Upload the Lambda function code to the S3 bucket
resource "aws_s3_object" "lambda_code_object" {
  bucket = aws_s3_bucket.lambda_code_bucket.bucket
  key    = "lambda_function_payload.zip"
  source = "./path/to/your/lambda_function_payload.zip"
}

# Lambda Function
resource "aws_lambda_function" "test_lambda" {
  function_name = "test_lambda"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  s3_bucket     = aws_s3_bucket.lambda_code_bucket.bucket
  s3_key        = aws_s3_object.lambda_code_object.key
}

# Allow EC2 events to trigger the Lambda function
resource "aws_lambda_permission" "allow_ec2_events" {
  statement_id  = "AllowEC2Events"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.test_lambda.function_name
  principal     = "ec2.amazonaws.com"
}

# CloudWatch Event Rule to trigger on EC2 image creation
resource "aws_cloudwatch_event_rule" "ec2_image_creation_rule" {
  name        = "ec2_image_creation_rule"
  description = "Triggers on EC2 image creation"
  event_pattern = jsonencode({
    "source": ["aws.ec2"],
    "detail-type": ["EC2 Image State Change"],
    "detail": {
      "state": ["available"]
    }
  })
}

# Set the CloudWatch event target to trigger the Lambda function
resource "aws_cloudwatch_event_target" "trigger_lambda_on_ec2_image_creation" {
  rule      = aws_cloudwatch_event_rule.ec2_image_creation_rule.name
  target_id = "TriggerLambdaOnEC2ImageCreation"
  arn       = aws_lambda_function.test_lambda.invoke_arn
}
```

This configuration now includes the `random` provider, which should resolve the error related to the missing provider. All other resources and configurations remain unchanged.

