### Description
This Terraform configuration creates a SageMaker user profile resource along with the necessary IAM role and policy. The SageMaker user profile requires an IAM role with specific permissions, which are defined in an IAM policy. The policy is then attached to the IAM role.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for the SageMaker user profile
resource "aws_iam_role" "sagemaker_user_profile_role" {
  name = "sagemaker-user-profile-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for the SageMaker user profile
resource "aws_iam_policy" "sagemaker_user_profile_policy" {
  name        = "sagemaker-user-profile-policy"
  description = "Policy for SageMaker user profile"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "sagemaker:*",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_sagemaker_user_profile_policy_to_role" {
  policy_arn = aws_iam_policy.sagemaker_user_profile_policy.arn
  role       = aws_iam_role.sagemaker_user_profile_role.name
}

# Create the SageMaker user profile
resource "aws_sagemaker_user_profile" "sagemaker_user_profile" {
  domain_id         = "your-domain-id"  # Replace with your actual domain ID
  user_profile_name = "example-user-profile"

  user_settings {
    execution_role = aws_iam_role.sagemaker_user_profile_role.arn
  }
}
```

### Notes
- Replace `"your-domain-id"` with the actual ID of your SageMaker domain.
- The IAM policy provided in the example grants broad permissions for SageMaker operations. Adjust the policy as needed to fit your security requirements.
- Ensure that the AWS region specified in the provider configuration matches the region where your SageMaker domain is located.

