### Description
This Terraform program creates an AWS SageMaker endpoint. It includes the necessary IAM roles, policies, and configurations to set up the endpoint. The program defines an IAM role with the required permissions, attaches a policy to this role, creates a SageMaker model, configures the endpoint, and finally creates the SageMaker endpoint itself.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for SageMaker endpoint execution
resource "aws_iam_role" "sagemaker_endpoint_execution_role" {
  name = "sagemaker-endpoint-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for SageMaker endpoint
resource "aws_iam_policy" "sagemaker_endpoint_policy" {
  name        = "sagemaker-endpoint-policy"
  description = "Policy for SageMaker endpoint execution"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_sagemaker_policy_to_role" {
  policy_arn = aws_iam_policy.sagemaker_endpoint_policy.arn
  role       = aws_iam_role.sagemaker_endpoint_execution_role.name
}

# SageMaker Model
resource "aws_sagemaker_model" "sagemaker_model" {
  name               = "sagemaker-model"
  execution_role_arn = aws_iam_role.sagemaker_endpoint_execution_role.arn

  primary_container {
    image = "763104351884.dkr.ecr.us-west-2.amazonaws.com/tensorflow-inference:2.3.0-cpu-py37-ubuntu18.04"
  }
}

# SageMaker Endpoint Configuration
resource "aws_sagemaker_endpoint_configuration" "sagemaker_endpoint_config" {
  name = "sagemaker-endpoint-config"

  production_variants {
    variant_name           = "variant-1"
    model_name             = aws_sagemaker_model.sagemaker_model.name
    initial_instance_count = 1
    instance_type          = "ml.m5.large"
  }
}

# SageMaker Endpoint
resource "aws_sagemaker_endpoint" "sagemaker_endpoint" {
  name                 = "sagemaker-endpoint"
  endpoint_config_name = aws_sagemaker_endpoint_configuration.sagemaker_endpoint_config.name
}
```

