  source_ami_id     = data.aws_ami.latest_amazon_linux_2_ami.id
  virtualization_type = "hvm"
  root_device_name    = "/dev/sda1"

  tags = {
    Name = "LatestAmazonLinux2AMICopy"
  }
}

variable "source_ami_region" {
  description = "The region where the source AMI is located"
  default     = "us-west-2"
}
