# Create a private subnet
resource "aws_subnet" "private_subnet" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = "us-west-2b"
  tags = {
    Name = "PrivateSubnet"
  }
}

# Create an IAM role for the EC2 Fleet
resource "aws_iam_role" "ec2_fleet_role" {
  name = "ec2-fleet-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM instance profile for the EC2 Fleet
resource "aws_iam_instance_profile" "ec2_fleet_instance_profile" {
  name = "ec2-fleet-instance-profile"
  role = aws_iam_role.ec2_fleet_role.name
}

# Create a launch template for the EC2 Fleet
resource "aws_launch_template" "ec2_fleet_launch_template" {
  name = "ec2-fleet-launch-template"

  image_id      = "ami-0c55b159cbfafe1f0" # Example AMI ID for AWS Linux 2
  instance_type = "t3.micro"
  key_name      = "my-key-pair"          # Replace with your key pair name

  iam_instance_profile {
    name = aws_iam_instance_profile.ec2_fleet_instance_profile.name
  }

  network_interfaces {
    associate_public_ip_address = true
    device_index                = 0
    subnet_id                   = aws_subnet.public_subnet.id
  }

  tags = {
    Name = "EC2FleetInstance"
  }
}

# Create an EC2 Fleet
resource "aws_ec2_fleet" "main_ec2_fleet" {
  launch_template_config {
    launch_template_specification {
      launch_template_id = aws_launch_template.ec2_fleet_launch_template.id
      version            = "$Latest"
    }

    override {
      instance_type = "t3.micro"
      weighted_capacity = 1
      subnet_id = aws_subnet.public_subnet.id
    }

    override {
      instance_type = "t3.micro"
      weighted_capacity = 1
      subnet_id = aws_subnet.private_subnet.id
    }
  }

  target_capacity_specification {
    default_target_capacity_type = "on-demand"
    total_target_capacity        = 5
    on_demand_target_capacity    = 5
  }

  spot_options {
    allocation_strategy = "lowestPrice"
    instance_interruption_behavior = "terminate"
    max_total_price = "10"
    min_target_capacity = 4
    single_availability_zone = false
    single_instance_type = false
  }

  tags = {
    Name = "MainEC2Fleet"
  }
}
```

### Explanation of Changes:
- The `allocation_strategy` in the `spot_options` block was corrected from `"lowest-price"` to `"lowestPrice"`, as per the Terraform AWS provider schema.

