### Description
This Terraform configuration sets up an IAM role and policy specifically for authenticating an ElastiCache user using IAM. The configuration includes:

1. **IAM Role**: An IAM role that allows ElastiCache to assume the role for authentication.
2. **IAM Policy**: A policy that defines the necessary permissions for ElastiCache user authentication.
3. **IAM Role Policy Attachment**: Attaches the policy to the IAM role.
4. **ElastiCache User**: An ElastiCache user that uses the IAM role for authentication.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for ElastiCache authentication
resource "aws_iam_role" "elasticache_user_auth_role" {
  name = "elasticache-user-auth-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticache.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for ElastiCache authentication
resource "aws_iam_policy" "elasticache_user_auth_policy" {
  name = "elasticache-user-auth-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "elasticache:DescribeUsers",
          "elasticache:ListTagsForResource",
          "elasticache:ModifyUser",
          "elasticache:UpdateUser"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_elasticache_policy_to_role" {
  policy_arn = aws_iam_policy.elasticache_user_auth_policy.arn
  role       = aws_iam_role.elasticache_user_auth_role.name
}

# ElastiCache User with IAM authentication
resource "aws_elasticache_user" "elasticache_user" {
  user_id       = "elasticache-user-id"
  user_name     = "elasticache-user-name"
  access_string = "on ~* +@all"
  engine        = "redis"

  authentication_mode {
    type = "iam"
  }
}
```

### Explanation
- **Provider Configuration**: Sets the AWS region to `us-west-2`.
- **IAM Role**: Defines an IAM role named `elasticache-user-auth-role` with a trust policy allowing ElastiCache to assume the role.
- **IAM Policy**: Defines an IAM policy named `elasticache-user-auth-policy` with permissions for ElastiCache user management.
- **IAM Role Policy Attachment**: Attaches the IAM policy to the IAM role.
- **ElastiCache User**: Creates an ElastiCache user with IAM authentication enabled by specifying the `authentication_mode` block with `type = "iam"`.

This configuration ensures that the ElastiCache user is authenticated using the specified IAM role and policy.

