      aws_subnet.subnet_az2.id,
      aws_subnet.subnet_az3.id,
    ]
    security_groups = [aws_security_group.sg.id]
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk_encryption_key.arn
  }

  depends_on = [
    aws_kms_key.msk_encryption_key,
    aws_iam_role_policy_attachment.attach_msk_policy_to_role
  ]
}
```

To use environment variables for AWS credentials, set the following environment variables in your shell before running Terraform:

```sh
export AWS_ACCESS_KEY_ID="your-access-key-id"
export AWS_SECRET_ACCESS_KEY="your-secret-access-key"
export AWS_DEFAULT_REGION="us-west-2"
```

Replace `"your-access-key-id"` and `"your-secret-access-key"` with your actual AWS access key ID and secret access key. This setup ensures that Terraform can authenticate with AWS and fetch the necessary availability zones.

