To address the error reported by the Terraform plan, we need to ensure that the `random_string` resource is properly defined and used. The error indicates that the `random_string` provider is not found, so we need to include it in the provider configuration.

Here is the corrected Terraform HCL program:

```hcl
provider "aws" {
  region = "us-west-2"
}

provider "random" {}

# IAM Role for MSK
resource "aws_iam_role" "msk_role" {
  name = "msk-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for MSK
resource "aws_iam_policy" "msk_policy" {
  name        = "msk-policy"
  description = "Policy for MSK to access S3, CloudWatch, and Kinesis Firehose"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          aws_s3_bucket.msk_s3_bucket.arn,
          "${aws_s3_bucket.msk_s3_bucket.arn}/*"
        ]
      },
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Effect   = "Allow"
        Resource = aws_cloudwatch_log_group.msk_log_group.arn
      },
      {
        Action = [
          "firehose:PutRecord",
          "firehose:PutRecordBatch"
        ]
        Effect   = "Allow"
        Resource = aws_kinesis_firehose_delivery_stream.msk_firehose_delivery_stream.arn
      }
    ]
  })
}

# Attach IAM Policy to Role
resource "aws_iam_role_policy_attachment" "attach_msk_policy_to_role" {
  policy_arn = aws_iam_policy.msk_policy.arn
  role       = aws_iam_role.msk_role.name
}

# S3 Bucket for MSK Logs
resource "aws_s3_bucket" "msk_s3_bucket" {
  bucket = "msk-broker-logs-bucket-${random_string.suffix.result}"
}

# CloudWatch Log Group for MSK Logs
resource "aws_cloudwatch_log_group" "msk_log_group" {
  name = "/aws/msk/broker-logs"
}

# Kinesis Firehose Delivery Stream for MSK Logs
resource "aws_kinesis_firehose_delivery_stream" "msk_firehose_delivery_stream" {
  name        = "msk-firehose-delivery-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn   = aws_iam_role.msk_role.arn
    bucket_arn = aws_s3_bucket.msk_s3_bucket.arn
  }
}

# MSK Cluster with 3 Broker Nodes
resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "msk-cluster"
  kafka_version          = "3.2.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets = [
      "subnet-0123456789abcdef0",
      "subnet-0123456789abcdef1",
      "subnet-0123456789abcdef2"
    ]
    security_groups = [
      "sg-0123456789abcdef0"
    ]
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_log_group.name
      }
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_firehose_delivery_stream.name
      }
      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msk_s3_bucket.id
        prefix  = "logs/msk-"
      }
    }
  }
}

# Random String for S3 Bucket Name
resource "random_string" "suffix" {
  length  = 8
  special = false
}
```

This configuration includes the `random` provider and defines the `random_string` resource, which is used to generate a unique suffix for the S3 bucket name. This should resolve the error related to the missing `random_string` provider.

