  name = "msk-connect-plugin-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "connect.amazonaws.com"
        }
      },
    ]
  })
}

# Attach a policy to the MSK Connect custom plugin role
resource "aws_iam_role_policy" "msk_connect_plugin_policy" {
  name = "msk-connect-plugin-policy"
  role = aws_iam_role.msk_connect_plugin_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
