  })
}

# Create an MSK Connect connector
resource "aws_mskconnect_connector" "msk_connect_connector" {
  name                 = "msk-connect-connector"
  kafkaconnect_version = "2.8.1"
  service_execution_role_arn = aws_iam_role.msk_connector_role.arn

