### Description
The Terraform program defines a DynamoDB table with data encryption at rest enabled using a KMS key. The KMS key is configured to allow the DynamoDB service to use it for encryption. The program includes a provider configuration for AWS in the "us-west-2" region and ensures that the KMS key policy is correctly set to allow the necessary actions for DynamoDB.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_kms_key" "kms_key_for_dynamodb" {
  description             = "KMS key for DynamoDB encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 10
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-default-1"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow use of the key"
        Effect = "Allow"
        Principal = {
          Service = "dynamodb.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

data "aws_caller_identity" "current" {}

resource "aws_dynamodb_table" "dynamodb_table_encrypted" {
  name           = "EncryptedDynamoDBTable"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "Id"

  attribute {
    name = "Id"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.kms_key_for_dynamodb.arn
  }
}
```

This configuration ensures that the DynamoDB table is encrypted at rest using the specified KMS key, and the KMS key policy is correctly set to allow the necessary actions for DynamoDB. The `data.aws_caller_identity.current` resource is used to dynamically fetch the account ID for the KMS key policy.

