### Description
This Terraform configuration creates an AWS Redshift cluster with example cluster parameters and sets up notifications on events associated with the parameter group. The configuration includes the creation of an SNS topic, an IAM role with the necessary permissions, and a Redshift event subscription.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an SNS topic for Redshift notifications
resource "aws_sns_topic" "redshift_cluster_notifications" {
  name = "redshift-cluster-notifications"
}

# Create an IAM role for Redshift to publish notifications to SNS
resource "aws_iam_role" "redshift_cluster_notification_role" {
  name = "redshift-cluster-notification-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy to allow Redshift to publish to the SNS topic
resource "aws_iam_policy" "redshift_cluster_notification_policy" {
  name        = "redshift-cluster-notification-policy"
  description = "Policy to allow Redshift to publish to SNS topic"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "sns:Publish"
        ]
        Effect = "Allow"
        Resource = aws_sns_topic.redshift_cluster_notifications.arn
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_redshift_cluster_notification_policy" {
  policy_arn = aws_iam_policy.redshift_cluster_notification_policy.arn
  role       = aws_iam_role.redshift_cluster_notification_role.name
}

# Subscribe to the SNS topic for notifications
resource "aws_sns_topic_subscription" "redshift_cluster_notification_subscription" {
  topic_arn = aws_sns_topic.redshift_cluster_notifications.arn
  protocol  = "email"
  endpoint  = "admin@example.com"
}

# Create a Redshift parameter group
resource "aws_redshift_parameter_group" "example_redshift_parameter_group" {
  name   = "example-redshift-parameter-group"
  family = "redshift-1.0"

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  parameter {
    name  = "query_group"
    value = "example"
  }

  parameter {
    name  = "enable_user_activity_logging"
    value = "true"
  }
}

# Create a Redshift cluster with the specified parameter group and notification settings
resource "aws_redshift_cluster" "example_redshift_cluster" {
  cluster_identifier = "example-redshift-cluster"
  node_type          = "dc2.large"
  database_name      = "exampledb"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  cluster_parameter_group_name = aws_redshift_parameter_group.example_redshift_parameter_group.name
  default_iam_role_arn = aws_iam_role.redshift_cluster_notification_role.arn
}
```

This Terraform configuration sets up an AWS Redshift cluster with custom parameters and configures notifications for events related to the parameter group. The SNS topic, IAM role, and policy ensure that Redshift can publish notifications to the specified email address.

