### Description
This Terraform program creates two S3 buckets: `mybucket` and `analytics_results_bucket`. It then configures analytics for `mybucket` and exports the results to `analytics_results_bucket`. The configuration uses bucket references rather than hardcoding bucket names.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "mybucket" {
  bucket = "mybucket"
  acl    = "private"
}

resource "aws_s3_bucket" "analytics_results_bucket" {
  bucket = "analytics-results-bucket"
  acl    = "private"
}

resource "aws_s3_bucket_analytics_configuration" "mybucket_analytics" {
  bucket = aws_s3_bucket.mybucket.id
  name   = "mybucket_analytics"

  storage_class_analysis {
    data_export {
      output_schema_version = "V_1"
      destination {
        s3_bucket_destination {
          bucket_arn = aws_s3_bucket.analytics_results_bucket.arn
          format     = "CSV"
        }
      }
    }
  }
}
```

