  bucket = "autograder-results-bucket-${random_string.suffix.result}"
  acl    = "private"

  tags = {
    Name        = "AutograderResultsBucket"
    Environment = "Production"
  }
}

# Random string suffix for the S3 bucket name to ensure uniqueness
resource "random_string" "suffix" {
  length  = 8
  special = false
}

# IAM Role for CodeBuild
resource "aws_iam_role" "codebuild_autograder_role" {
  name = "codebuild-autograder-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = "CodeBuildAutograderRole"
    Environment = "Production"
  }
}

# IAM Policy to allow CodeBuild to access the S3 bucket
resource "aws_iam_policy" "codebuild_s3_access_policy" {
  name        = "codebuild-s3-access-policy"
  description = "Policy to allow CodeBuild to access the S3 bucket."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.autograder_results_bucket.arn,
          "${aws_s3_bucket.autograder_results_bucket.arn}/*"
        ]
      }
    ]
  })

  tags = {
    Name        = "CodeBuildS3AccessPolicy"
    Environment = "Production"
  }
}

# Attach the S3 access policy to the CodeBuild IAM role
resource "aws_iam_role_policy_attachment" "attach_codebuild_s3_policy" {
  policy_arn = aws_iam_policy.codebuild_s3_access_policy.arn
  role       = aws_iam_role.codebuild_autograder_role.name
}

# CodeBuild Project to run students' code
resource "aws_codebuild_project" "autograder_codebuild_project" {
  name          = "autograder-codebuild-project"
  description   = "CodeBuild project for running students' code."
  service_role  = aws_iam_role.codebuild_autograder_role.arn
  build_timeout = 60

  artifacts {
    type = "S3"
    location = "${aws_s3_bucket.autograder_results_bucket.bucket}/build-artifacts"
  }

  cache {
    type     = "S3"
    location = aws_s3_bucket.autograder_results_bucket.bucket
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  source {
    type            = "GITHUB"
    location        = "https://github.com/example/example.git"
    git_clone_depth = 1
  }

  tags = {
    Name        = "AutograderCodeBuildProject"
    Environment = "Production"
  }
}
```

