# Random string suffix for the S3 bucket name
resource "random_string" "suffix" {
  length  = 8
  special = false
}

# IAM Role for CodeBuild
resource "aws_iam_role" "autograder_codebuild_role" {
  name = "AutograderCodeBuildRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "AutograderCodeBuildRole"
  }
}

# IAM Policy for CodeBuild
resource "aws_iam_role_policy" "autograder_codebuild_policy" {
  role = aws_iam_role.autograder_codebuild_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeDhcpOptions",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVpcs"
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = "ec2:CreateNetworkInterfacePermission"
        Effect = "Allow"
        Resource = "arn:aws:ec2:us-west-2:*:network-interface/*"
        Condition = {
          StringEquals = {
            "ec2:Subnet" = aws_subnet.autograder_subnet.arn
            "ec2:AuthorizedService" = "codebuild.amazonaws.com"
          }
        }
      },
      {
        Action = "s3:*"
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.autograder_results_bucket.arn,
          "${aws_s3_bucket.autograder_results_bucket.arn}/*"
        ]
      }
    ]
  })
}

# CodeBuild project to run the autograder
resource "aws_codebuild_project" "autograder_codebuild_project" {
  name          = "AutograderCodeBuildProject"
  description   = "CodeBuild project for autograding"
  service_role  = aws_iam_role.autograder_codebuild_role.arn

  artifacts {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  source {
    type     = "GITHUB"
    location = "https://github.com/example/example.git"
  }

  vpc_config {
    vpc_id             = aws_vpc.autograder_vpc.id
    subnets            = [aws_subnet.autograder_subnet.id]
    security_group_ids = [aws_security_group.autograder_sg.id]
  }

  tags = {
    Name = "AutograderCodeBuildProject"
  }
}
```

