### Description

This Terraform program provisions an EC2 instance and sets up a daily backup at midnight using AWS Backup. The program includes the following resources:

1. **AWS EC2 Instance**: An EC2 instance is created with a specified AMI, instance type, and key pair.
2. **AWS Backup Vault**: A backup vault is created to store the backups.
3. **AWS Backup Plan**: A backup plan is defined to specify the backup schedule.
4. **AWS Backup Selection**: The EC2 instance is selected for backup according to the backup plan.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "ami_id" {
  description = "The AMI ID to use for the EC2 instance"
  default     = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Ubuntu Server 20.04 LTS
}

variable "instance_type" {
  description = "The instance type to use for the EC2 instance"
  default     = "t3.micro"
}

variable "key_name" {
  description = "The key pair name to use for the EC2 instance"
  default     = "my-key-pair"
}

resource "aws_instance" "ec2_instance" {
  ami           = var.ami_id
  instance_type = var.instance_type
  key_name      = var.key_name
}

resource "aws_backup_vault" "backup_vault" {
  name = "my-backup-vault"
}

resource "aws_backup_plan" "backup_plan" {
  name = "daily-backup-plan"

  rule {
    rule_name         = "daily-backup-rule"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = "cron(0 0 * * ? *)"  # Daily at midnight

    lifecycle {
      delete_after = 30  # Retain backups for 30 days
    }
  }
}

resource "aws_backup_selection" "backup_selection" {
  iam_role_arn = aws_iam_role.backup_role.arn
  name         = "ec2-instance-selection"
  plan_id      = aws_backup_plan.backup_plan.id

  resources = [
    aws_instance.ec2_instance.arn
  ]
}

resource "aws_iam_role" "backup_role" {
  name = "backup-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_policy" "backup_policy" {
  name = "backup-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:StartInstances",
          "ec2:StopInstances",
          "ec2:TerminateInstances",
          "ec2:DescribeInstances",
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:CreateSnapshot",
          "ec2:DeleteSnapshot"
        ]
        Effect = "Allow"
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_policy_attachment" {
  policy_arn = aws_iam_policy.backup_policy.arn
  role       = aws_iam_role.backup_role.name
}
```

This Terraform configuration sets up an EC2 instance and configures AWS Backup to perform daily backups at midnight. The IAM role and policy ensure that the backup service has the necessary permissions to perform the backups.

