    rule_name         = "daily-backup-rule"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = "cron(0 0 * * ? *)"  # Daily at midnight

    lifecycle {
      delete_after = 30  # Retain backups for 30 days
    }
  }
}

# Create an AWS Backup selection
resource "aws_backup_selection" "backup_selection" {
  iam_role_arn = aws_iam_role.backup_role.arn
  plan_id      = aws_backup_plan.backup_plan.id
  name         = "my-backup-selection"

  resources = [
    aws_instance.ec2_instance.arn
  ]
}

# Create an IAM role for AWS Backup
resource "aws_iam_role" "backup_role" {
  name = "aws-backup-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      },
    ]
  })
}

# Attach a policy to the IAM role for AWS Backup
resource "aws_iam_role_policy" "backup_policy" {
  name   = "aws-backup-policy"
  role   = aws_iam_role.backup_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:StartInstances",
          "ec2:StopInstances",
          "ec2:TerminateInstances",
          "ec2:DescribeInstances",
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:CreateSnapshot",
          "ec2:CreateTags",
          "ec2:DeleteSnapshot"
        ]
        Effect = "Allow"
        Resource = "*"
      },
    ]
  })
}
```

In this corrected version, the `public_key` attribute in the `aws_key_pair` resource is replaced with a placeholder public key string. You should replace `"ssh-rsa AAAAB3NzaC1yc2EAAAADAQABAAABAQC..."` with the actual content of your public key file. This ensures that the Terraform configuration is valid and can be deployed without errors related to missing files.

