### Description

This Terraform program sets up an AWS infrastructure to run a code every day at 7 UTC using AWS EventBridge. It includes the following components:

1. **IAM Role and Policy**: An IAM role (`eventbridge_lambda_execution_role`) and a policy (`lambda_basic_execution_policy`) are created to grant the necessary permissions for the Lambda function to execute.
2. **Lambda Function**: A Lambda function (`daily_code_runner`) is defined to run the code. The function is assigned the IAM role created earlier.
3. **EventBridge Rule**: An EventBridge rule (`daily_schedule_rule`) is set up to trigger the Lambda function daily at 7 UTC.
4. **Lambda Permission**: A permission (`allow_eventbridge_invocation`) is granted to allow EventBridge to invoke the Lambda function.
5. **EventBridge Target**: A target (`trigger_lambda_from_eventbridge`) is configured to link the EventBridge rule to the Lambda function.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Lambda Execution
resource "aws_iam_role" "eventbridge_lambda_execution_role" {
  name = "eventbridge_lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lambda Basic Execution
resource "aws_iam_policy" "lambda_basic_execution_policy" {
  name        = "lambda_basic_execution_policy"
  description = "Basic execution policy for Lambda functions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

# Attach the policy to the Lambda execution role
resource "aws_iam_role_policy_attachment" "attach_lambda_policy_to_role" {
  policy_arn = aws_iam_policy.lambda_basic_execution_policy.arn
  role       = aws_iam_role.eventbridge_lambda_execution_role.name
}

# Lambda Function to run code daily
resource "aws_lambda_function" "daily_code_runner" {
  function_name = "daily_code_runner"
  role          = aws_iam_role.eventbridge_lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "function.zip"

  environment {
    variables = {
      LOG_LEVEL = "INFO"
    }
  }
}

# EventBridge Rule to trigger the Lambda function daily at 7 UTC
resource "aws_cloudwatch_event_rule" "daily_schedule_rule" {
  name                = "daily_schedule_rule"
  schedule_expression = "cron(0 7 * * ? *)"
}

# Permission for EventBridge to invoke the Lambda function
resource "aws_lambda_permission" "allow_eventbridge_invocation" {
  statement_id  = "AllowExecutionFromEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.daily_code_runner.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.daily_schedule_rule.arn
}

# Target to trigger the Lambda function from the EventBridge rule
resource "aws_cloudwatch_event_target" "trigger_lambda_from_eventbridge" {
  rule      = aws_cloudwatch_event_rule.daily_schedule_rule.name
  target_id = "TriggerDailyCodeRunner"
  arn       = aws_lambda_function.daily_code_runner.arn
}
```

### Notes

- Ensure that the Lambda function code is provided and correctly configured in the `filename` attribute.
- The EventBridge rule schedule expression is set to `cron(0 7 * * ? *)` to trigger the Lambda function daily at 7 UTC.
- The IAM role and policy ensure that the Lambda function has the necessary permissions to execute and write logs to CloudWatch.

