Below is the complete Terraform HCL program that meets the requirements specified in the prompt. It includes the creation of an IAM role for the Lambda function, the Lambda function itself, an EventBridge rule, and the necessary permissions and targets to link them together.

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Lambda Execution
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })
}

# Attach Basic Execution Policy to Lambda Role
resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# Lambda Function
resource "aws_lambda_function" "cron_lambda_function" {
  function_name = "cron-lambda-function"
  filename      = "./supplement/lambda_func.zip"
  handler       = "lambda_func.lambda_handler"
  runtime       = "python3.12"
  role          = aws_iam_role.lambda_execution_role.arn
}

# EventBridge Rule
resource "aws_cloudwatch_event_rule" "cron_event_rule" {
  name                = "cron"
  schedule_expression = "cron(0 7 * * ? *)"
}

# Lambda Permission for EventBridge to Invoke Lambda Function
resource "aws_lambda_permission" "allow_eventbridge_invocation" {
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.cron_lambda_function.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.cron_event_rule.arn
}

# EventBridge Target to Trigger Lambda Function
resource "aws_cloudwatch_event_target" "cron_event_target" {
  rule      = aws_cloudwatch_event_rule.cron_event_rule.name
  target_id = "cron_lambda_target"
  arn       = aws_lambda_function.cron_lambda_function.arn
}
```

This Terraform configuration sets up the necessary components to create an EventBridge rule that triggers a Lambda function every day at 7 UTC. The IAM role and policy attachments ensure that the Lambda function has the necessary permissions to execute.

