  name = "cloudfront-origin-access-identity-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy to allow read access to S3 bucket
resource "aws_iam_policy" "s3_read_policy" {
  name        = "s3-read-policy"
  description = "Policy to allow read access to S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_s3_bucket.video_streaming_bucket.arn}/*"
        ]
      }
    ]
  })
}

# Attach S3 read policy to CloudFront origin access identity role
resource "aws_iam_role_policy_attachment" "attach_s3_read_policy_to_role" {
  policy_arn = aws_iam_policy.s3_read_policy.arn
  role       = aws_iam_role.cloudfront_origin_access_identity_role.name
}

# CloudFront Distribution to distribute video content globally
resource "aws_cloudfront_distribution" "video_streaming_distribution" {
  enabled             = true
  is_ipv6_enabled     = true
  comment             = "Video Streaming Distribution"
  default_root_object = "index.html"

  origin {
    domain_name              = aws_s3_bucket.video_streaming_bucket.bucket_regional_domain_name
    origin_access_control_id = aws_iam_role.cloudfront_origin_access_identity_role.unique_id
