    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

# Route53 Zone for video streaming domain
resource "aws_route53_zone" "video_streaming_domain_zone" {
  name = "example.com"
}

# Route53 Record to map domain to CloudFront distribution
