provider "aws" {
  region = "us-east-1"
}

provider "random" {}

# S3 Bucket to store video content
resource "aws_s3_bucket" "video_content_bucket" {
  bucket = "video-content-bucket-${random_string.suffix.result}"
  acl    = "private"

  tags = {
    Name = "VideoContentBucket"
  }
}

# Random string suffix for unique bucket name
resource "random_string" "suffix" {
  length  = 8
  special = false
}

# IAM Role for CloudFront to access S3
resource "aws_iam_role" "cloudfront_origin_access_identity_role" {
  name = "CloudFrontOriginAccessIdentityRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy to allow S3 read access
resource "aws_iam_policy" "s3_read_policy" {
  name        = "S3ReadPolicy"
  description = "Policy to allow reading from S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_s3_bucket.video_content_bucket.arn}/*"
        ]
      }
    ]
  })
}

# Attach the S3 read policy to the CloudFront role
resource "aws_iam_role_policy_attachment" "attach_s3_read_policy_to_role" {
  policy_arn = aws_iam_policy.s3_read_policy.arn
  role       = aws_iam_role.cloudfront_origin_access_identity_role.name
}

# CloudFront Origin Access Control
resource "aws_cloudfront_origin_access_control" "origin_access_control" {
  name                              = "OriginAccessControl"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "never"
  signing_protocol                  = "sigv4"
}

# CloudFront Distribution
resource "aws_cloudfront_distribution" "video_streaming_distribution" {
  enabled             = true
  is_ipv6_enabled     = true
  comment             = "Video Streaming Distribution"
  default_root_object = "index.html"

  origin {
    domain_name              = aws_s3_bucket.video_content_bucket.bucket_regional_domain_name
    origin_access_control_id = aws_cloudfront_origin_access_control.origin_access_control.id
    origin_id                = "myS3Origin"
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "myS3Origin"

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
