  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

# Route53 Zone for the video streaming site
resource "aws_route53_zone" "video_streaming_zone" {
  name = "video-streaming-site.com"

  tags = {
    Name = "VideoStreamingZone"
  }
}

# Route53 Record to map the domain name to the CloudFront distribution
