    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "video-streaming-sg-web"
  }
}

# Launch Configuration
resource "aws_launch_configuration" "video_streaming_lc" {
  image_id      = "ami-0c55b159cbfafe1f0"  # Example AMI ID for t3.micro instance
  instance_type = "t3.micro"
  security_groups = [
    aws_security_group.video_streaming_sg_web.name
  ]
  user_data = <<-EOF
              #!/bin/bash
              echo "Hello, World!" > index.html
              nohup python -m http.server 80 &
              EOF
}

# Auto Scaling Group
resource "aws_autoscaling_group" "video_streaming_asg" {
  launch_configuration = aws_launch_configuration.video_streaming_lc.name
  vpc_zone_identifier  = [aws_subnet.video_streaming_subnet_private.id]
  min_size             = 2
  max_size             = 5
  health_check_type    = "EC2"
  health_check_grace_period = 300
  tag {
    key                 = "Name"
    value               = "video-streaming-asg"
    propagate_at_launch = true
  }
}

# Elastic Load Balancer
resource "aws_elb" "video_streaming_elb" {
  name               = "video-streaming-elb"
  availability_zones = ["us-west-2a"]
  subnets            = [aws_subnet.video_streaming_subnet_public.id]
  security_groups    = [aws_security_group.video_streaming_sg_web.id]
  instances          = aws_autoscaling_group.video_streaming_asg.instances

  listener {
    instance_port     = 80
    instance_protocol = "HTTP"
    lb_port           = 80
    lb_protocol       = "HTTP"
  }

  health_check {
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 5
    target              = "HTTP:80/"
    interval            = 30
  }

  tags = {
    Name = "video-streaming-elb"
  }
}
