provider "aws" {
  region = "us-west-2"
}

variable "domain_name" {
  description = "The domain name for the video streaming site"
  default     = "example.com"
}

resource "aws_vpc" "video_streaming_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "video_streaming_public_subnet" {
  vpc_id                  = aws_vpc.video_streaming_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
}

resource "aws_subnet" "video_streaming_private_subnet" {
  vpc_id                  = aws_vpc.video_streaming_vpc.id
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = false
}

resource "aws_internet_gateway" "video_streaming_igw" {
  vpc_id = aws_vpc.video_streaming_vpc.id
}

resource "aws_route_table" "video_streaming_public_route_table" {
  vpc_id = aws_vpc.video_streaming_vpc.id
}

resource "aws_route" "video_streaming_public_route" {
  route_table_id         = aws_route_table.video_streaming_public_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.video_streaming_igw.id
}

resource "aws_route_table_association" "video_streaming_public_subnet_association" {
  subnet_id      = aws_subnet.video_streaming_public_subnet.id
  route_table_id = aws_route_table.video_streaming_public_route_table.id
}

resource "aws_security_group" "video_streaming_lb_sg" {
  vpc_id = aws_vpc.video_streaming_vpc.id
  name   = "video_streaming_lb_sg"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "video_streaming_ec2_sg" {
  vpc_id = aws_vpc.video_streaming_vpc.id
  name   = "video_streaming_ec2_sg"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "video_streaming_lb" {
  name               = "video-streaming-lb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.video_streaming_lb_sg.id]
  subnets            = [aws_subnet.video_streaming_public_subnet.id]

  tags = {
    Name = "video-streaming-lb"
  }
}

resource "aws_lb_target_group" "video_streaming_lb_target_group" {
  name     = "video-streaming-lb-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.video_streaming_vpc.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_lb_listener" "video_streaming_lb_listener" {
  load_balancer_arn = aws_lb.video_streaming_lb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.video_streaming_lb_target_group.arn
  }
}

resource "aws_instance" "video_streaming_server" {
  count         = 3
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.video_streaming_private_subnet.id
  security_groups = [aws_security_group.video_streaming_ec2_sg.name]

  tags = {
    Name = "video-streaming-server-${count.index}"
  }
}

resource "aws_lb_target_group_attachment" "video_streaming_lb_target_group_attachment" {
  count            = 3
  target_group_arn = aws_lb_target_group.video_streaming_lb_target_group.arn
  target_id        = element(aws_instance.video_streaming_server[*].id, count.index)
  port             = 80
}

resource "aws_route53_zone" "video_streaming_domain_zone" {
  name = var.domain_name
}

resource "aws_route53_record" "video_streaming_domain_record" {
  zone_id = aws_route53_zone.video_streaming_domain_zone.zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_lb.video_streaming_lb.dns_name
    zone_id                = aws_lb.video_streaming_lb.zone_id
    evaluate_target_health = true
  }
}
