### Description

This Terraform configuration sets up the infrastructure for a video streaming site with load balancing. It includes the following resources:

1. **AWS VPC**: A Virtual Private Cloud to host the video streaming infrastructure.
2. **AWS Subnet**: A subnet within the VPC where EC2 instances will be launched.
3. **AWS Security Group**: A security group to control inbound and outbound traffic for the EC2 instances.
4. **AWS EC2 Instance**: An EC2 instance serving as a server for the video streaming service.
5. **AWS Load Balancer**: A load balancer to distribute incoming traffic across multiple servers.
6. **AWS Load Balancer Target Group**: A target group to register the EC2 instances with the load balancer.
7. **AWS Route53 Zone**: A Route53 zone to manage DNS records for the video streaming domain.
8. **AWS Route53 Record**: A Route53 record to map the domain name to the load balancer.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "video_streaming_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "VideoStreamingVPC"
  }
}

resource "aws_subnet" "video_streaming_subnet" {
  vpc_id                  = aws_vpc.video_streaming_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = true
  tags = {
    Name = "VideoStreamingSubnet"
  }
}

resource "aws_security_group" "video_streaming_sg" {
  vpc_id = aws_vpc.video_streaming_vpc.id
  name   = "video_streaming_sg"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "VideoStreamingSG"
  }
}

resource "aws_instance" "video_streaming_server" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Amazon Linux 2
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.video_streaming_subnet.id
  security_groups = [aws_security_group.video_streaming_sg.name]

  tags = {
    Name = "VideoStreamingServer"
  }
}

resource "aws_lb" "video_streaming_lb" {
  name            = "video-streaming-lb"
  internal        = false
  load_balancer_type = "application"
  security_groups = [aws_security_group.video_streaming_sg.id]
  subnets         = [aws_subnet.video_streaming_subnet.id]

  tags = {
    Name = "VideoStreamingLB"
  }
}

resource "aws_lb_target_group" "video_streaming_tg" {
  name     = "video-streaming-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.video_streaming_vpc.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "VideoStreamingTG"
  }
}

resource "aws_lb_listener" "video_streaming_listener" {
  load_balancer_arn = aws_lb.video_streaming_lb.arn
  port              = "80"
  protocol          = "HTTP"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.video_streaming_tg.arn
  }
}

resource "aws_route53_zone" "video_streaming_zone" {
  name = "example.com"
  tags = {
    Name = "VideoStreamingZone"
  }
}

resource "aws_route53_record" "video_streaming_record" {
  zone_id = aws_route53_zone.video_streaming_zone.zone_id
  name    = "www"
  type    = "A"

  alias {
    name                   = aws_lb.video_streaming_lb.dns_name
    zone_id                = aws_lb.video_streaming_lb.zone_id
    evaluate_target_health = true
  }
}
```

