Below is a complete Terraform HCL program that provisions a secure PostgreSQL database instance within a specified AWS VPC, leveraging AWS services like RDS, subnets, and KMS for encryption. It sets up a custom parameter group for PostgreSQL settings, and a security group to manage access. The database instance is configured with specifications like storage size, engine version, multi-AZ deployment for high availability, and encryption using a KMS key.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "database_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "DatabaseVPC"
  }
}

resource "aws_subnet" "database_subnet_private" {
  vpc_id            = aws_vpc.database_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "DatabasePrivateSubnet"
  }
}

resource "aws_subnet" "database_subnet_public" {
  vpc_id            = aws_vpc.database_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2a"
  map_public_ip_on_launch = true
  tags = {
    Name = "DatabasePublicSubnet"
  }
}

resource "aws_security_group" "database_sg" {
  vpc_id = aws_vpc.database_vpc.id
  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "DatabaseSecurityGroup"
  }
}

resource "aws_db_parameter_group" "database_param_group" {
  family = "postgres13"
  name   = "custom-postgres-param-group"
  parameter {
    name  = "rds.logical_replication"
    value = "1"
  }
  tags = {
    Name = "CustomPostgresParamGroup"
  }
}

resource "aws_kms_key" "database_kms_key" {
  description             = "KMS key for encrypting the database"
  deletion_window_in_days = 10
  tags = {
    Name = "DatabaseKMSKey"
  }
}

resource "aws_db_instance" "database_instance" {
  instance_class       = "db.t3.micro"
  engine               = "postgres"
  engine_version       = "13.7"
  allocated_storage    = 20
  username             = "admin"
  password             = "securepassword"
  db_subnet_group_name = aws_db_subnet_group.database_subnet_group.name
  vpc_security_group_ids = [aws_security_group.database_sg.id]
