provider "aws" {
  region = "us-west-2"
}

variable "subnet_ids" {
  description = "List of subnet IDs where the RDS instance will be deployed."
  type        = list(string)
  default     = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]
}

variable "db_instance_class" {
  description = "The instance class of the RDS instance."
  type        = string
  default     = "db.t3.micro"
}

variable "db_name" {
  description = "The name of the database."
  type        = string
  default     = "airbyte_db"
}

variable "username" {
  description = "The master username for the database."
  type        = string
  default     = "airbyte_user"
}

variable "password" {
  description = "The master password for the database."
  type        = string
  sensitive   = true
  default     = "securepassword123"
}

resource "aws_db_subnet_group" "airbyte_postgres_subnet_group" {
  name       = "airbyte-postgres-subnet-group"
  subnet_ids = var.subnet_ids
}

resource "aws_iam_role" "airbyte_postgres_rds_role" {
  name = "airbyte-postgres-rds-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "airbyte_postgres_rds_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSFullAccess"
  role       = aws_iam_role.airbyte_postgres_rds_role.name
}

resource "aws_db_instance" "airbyte_postgres_instance" {
  instance_class      = var.db_instance_class
  allocated_storage   = 20
  engine              = "postgres"
  engine_version      = "15"
  db_name             = var.db_name
  username            = var.username
  password            = var.password
  db_subnet_group_name = aws_db_subnet_group.airbyte_postgres_subnet_group.name
  apply_immediately   = true
  skip_final_snapshot = true
  publicly_accessible = true
}
