### Description
This Terraform configuration creates an AWS Lightsail instance and a MySQL database on that instance. It includes the necessary IAM roles and policies to ensure proper permissions for the Lightsail instance and the RDS operations.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Lightsail instance
resource "aws_iam_role" "lightsail_instance_role" {
  name = "lightsail-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lightsail instance
resource "aws_iam_policy" "lightsail_instance_policy" {
  name        = "lightsail-instance-policy"
  description = "Policy for Lightsail instance to manage RDS operations"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "rds:*",
          "ec2:*",
          "lightsail:*"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM policy to IAM role
resource "aws_iam_role_policy_attachment" "attach_lightsail_policy_to_role" {
  policy_arn = aws_iam_policy.lightsail_instance_policy.arn
  role       = aws_iam_role.lightsail_instance_role.name
}

# Create Lightsail instance
resource "aws_lightsail_instance" "my_lightsail_instance" {
  name              = "my-lightsail-instance"
  availability_zone = "us-east-1a"
  blueprint_id      = "amazon_linux_2"
  bundle_id         = "nano_3_0"

  depends_on = [aws_iam_role_policy_attachment.attach_lightsail_policy_to_role]
}

# Create MySQL database on Lightsail instance
resource "aws_db_instance" "my_mysql_database" {
  instance_class = "db.t2.micro"
  allocated_storage    = 20
  engine               = "mysql"
  engine_version       = "8.0"
  username             = "admin"
  password             = "securepassword"
  db_name              = "mydatabase"

  depends_on = [aws_lightsail_instance.my_lightsail_instance]
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **IAM Role and Policy**: An IAM role and policy are created to allow the Lightsail instance to perform necessary RDS operations.
3. **Lightsail Instance**: A Lightsail instance is created with the specified blueprint and bundle IDs.
4. **MySQL Database**: A MySQL database is created on the Lightsail instance with the specified instance class, storage, engine, and credentials.

This configuration ensures that the Lightsail instance has the necessary permissions to create and manage the MySQL database.

### Description

This Terraform program creates an AWS Lightsail instance to host a PostgreSQL database. The database is configured to apply changes immediately instead of waiting for a maintenance window. Additionally, it sets up an IAM role and policy required for Lightsail to manage the PostgreSQL database.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "lightsail_postgres_role" {
  name = "lightsail-postgres-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lightsail_postgres_policy" {
  name        = "lightsail-postgres-policy"
  description = "Policy for Lightsail to manage PostgreSQL database"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "rds:*",
          "ec2:*",
          "elasticloadbalancing:*",
          "autoscaling:*",
          "cloudwatch:*",
          "logs:*"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_lightsail_postgres_policy" {
  policy_arn = aws_iam_policy.lightsail_postgres_policy.arn
  role       = aws_iam_role.lightsail_postgres_role.name
}

resource "aws_lightsail_instance" "lightsail_postgres_instance" {
  availability_zone = "us-east-1a"
  blueprint_id      = "postgres_12"
  bundle_id         = "micro_1_0"
  name              = "lightsail-postgres-instance"
  tags = {
    Name = "LightsailPostgresInstance"
  }
}

resource "aws_lightsail_database" "lightsail_postgres_database" {
  relational_database_name = "my-postgres-db"
  availability_zone        = "us-east-1a"
  master_database_name     = "mydb"
  master_password          = "securepassword123"
  master_username          = "admin"
  blueprint_id             = "postgres_12"
  bundle_id                = "micro_1_0"
  apply_immediately        = true
  tags = {
    Name = "LightsailPostgresDatabase"
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **IAM Role**: An IAM role named `lightsail-postgres-role` is created with a trust policy allowing Lightsail to assume the role.
3. **IAM Policy**: An IAM policy named `lightsail-postgres-policy` is created with permissions to manage RDS, EC2, Elastic Load Balancing, Auto Scaling, CloudWatch, and Logs.
4. **IAM Role Policy Attachment**: The IAM policy is attached to the IAM role.
5. **Lightsail Instance**: A Lightsail instance is created with the specified blueprint and bundle IDs, and tagged for identification.
6. **Lightsail Database**: A Lightsail database is created with the specified settings, including enabling immediate application of changes.

