Below is a complete Terraform HCL program that creates a Lightsail instance with access to an S3 bucket. The program includes the necessary IAM roles, policies, and bucket policies to ensure proper access.

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "lightsail_bucket_access_role" {
  name = "lightsail-s3-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lightsail_bucket_access_policy" {
  name        = "lightsail-s3-access-policy"
  description = "Policy allowing Lightsail to access S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::example-bucket/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_lightsail_bucket_access_policy" {
  policy_arn = aws_iam_policy.lightsail_bucket_access_policy.arn
  role       = aws_iam_role.lightsail_bucket_access_role.name
}

resource "aws_s3_bucket" "example_s3_bucket" {
  bucket = "example-bucket"
}

resource "aws_s3_bucket_policy" "lightsail_bucket_policy" {
  bucket = aws_s3_bucket.example_s3_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Effect   = "Allow"
        Principal = {
          AWS = aws_iam_role.lightsail_bucket_access_role.arn
        }
        Resource = "arn:aws:s3:::example-bucket/*"
      }
    ]
  })
}

resource "aws_lightsail_instance" "example_lightsail_instance" {
  availability_zone = "us-east-1b"
  blueprint_id      = "amazon_linux_2"
  bundle_id         = "nano_3_0"
  name              = "example-lightsail-instance"
}
```

This Terraform configuration does the following:
1. Sets up the AWS provider with the region `us-east-1`.
2. Creates an IAM role (`lightsail_bucket_access_role`) that allows Lightsail to assume the role.
3. Defines an IAM policy (`lightsail_bucket_access_policy`) that grants `GetObject`, `PutObject`, and `DeleteObject` permissions on the specified S3 bucket.
4. Attaches the IAM policy to the IAM role.
5. Creates an S3 bucket (`example_s3_bucket`) with the name `example-bucket`.
6. Sets up an S3 bucket policy (`lightsail_bucket_policy`) that allows the IAM role to perform the specified actions on the bucket.
7. Creates a Lightsail instance (`example_lightsail_instance`) in the specified availability zone, using the specified blueprint and bundle.

This setup ensures that the Lightsail instance has the necessary permissions to access the specified S3 bucket.

