Description:
The Terraform program defines an S3 Glacier vault and configures AWS Data Lifecycle Manager (DLM) to manage the lifecycle of S3 objects by transitioning them to the Glacier vault. The program includes creating an S3 Glacier vault, an SNS topic for notifications, an IAM role for DLM, an IAM policy granting necessary permissions, and a DLM lifecycle policy. The configuration ensures that the DLM lifecycle policy adheres to the correct schema requirements by adjusting the `policy_type`, `interval`, and `interval_unit`.

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create an S3 Glacier vault
resource "aws_glacier_vault" "my_archive" {
  name = "MyArchive"

  notification {
    sns_topic = aws_sns_topic.glacier_sns_topic.arn
    events    = ["ArchiveRetrievalCompleted", "InventoryRetrievalCompleted"]
  }

  tags = {
    Test = "MyArchive"
  }
}

# Create an SNS topic for Glacier notifications
resource "aws_sns_topic" "glacier_sns_topic" {
  name = "glacier-sns-topic"
}

# Create an IAM role for AWS Data Lifecycle Manager
resource "aws_iam_role" "data_lifecycle_manager_role" {
  name = "dlm-glacier-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dlm.amazonaws.com"
        }
      }
    ]
  })
}

# Define the policy that allows AWS Data Lifecycle Manager to access the S3 Glacier vault
resource "aws_iam_policy" "data_lifecycle_manager_policy" {
  name = "dlm-glacier-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "glacier:InitiateJob",
          "glacier:GetJobOutput",
          "glacier:ListJobs",
          "glacier:DescribeVault",
          "glacier:UploadArchive",
          "glacier:DeleteArchive"
        ]
        Effect = "Allow"
        Resource = aws_glacier_vault.my_archive.arn
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_data_lifecycle_manager_policy" {
  policy_arn = aws_iam_policy.data_lifecycle_manager_policy.arn
  role       = aws_iam_role.data_lifecycle_manager_role.name
}

# Create a DLM lifecycle policy to manage the lifecycle of S3 objects using the S3 Glacier vault
resource "aws_dlm_lifecycle_policy" "dlm_lifecycle_policy" {
  description          = "Transition S3 objects to Glacier vault"
  execution_role_arn = aws_iam_role.data_lifecycle_manager_role.arn

  policy_details {
    policy_type = "EVENT_BASED_POLICY"

    resource_locations = ["CLOUD"]

    resource_types = ["VOLUME"]

    event_source {
      type = "MANAGED_CWE"
      parameters = {
        description = "Daily backup"
      }
    }

    schedule {
      name     = "daily-backup"
      copy_tags  = true
      create_rule {
        interval      = 24
        interval_unit = "HOURS"
        times         = ["23:00"]
      }
      retain_rule {
        count = 3
      }
    }

    target_tags = {
      Name = "backup"
    }
  }
}
