### Description
This Terraform configuration creates an Application Load Balancer named `test-lb-tf` with two subnets and a security group. The load balancer is not internal and has deletion protection enabled. The subnets are assumed to be in different availability zones for high availability.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# Create a VPC for the subnets and security group
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

# Create two subnets in different availability zones
resource "aws_subnet" "subnet_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

# Create a security group for the load balancer
resource "aws_security_group" "test_lb_sg" {
  name        = "test-lb-sg"
  description = "Security group for the application load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create the Application Load Balancer
resource "aws_lb" "test_lb_tf" {
  name               = "test-lb-tf"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.test_lb_sg.id]

  subnet_mapping {
    subnet_id = aws_subnet.subnet_1.id
  }

  subnet_mapping {
    subnet_id = aws_subnet.subnet_2.id
  }

  enable_deletion_protection = true
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured with a specific region (`us-west-2`).
2. **VPC Creation**: A VPC is created with a CIDR block of `10.0.0.0/16`.
3. **Subnet Creation**: Two subnets are created in different availability zones (`us-west-2a` and `us-west-2b`) within the VPC.
4. **Security Group Creation**: A security group is created for the load balancer, allowing HTTP traffic from anywhere and unrestricted egress.
5. **Application Load Balancer Creation**: An Application Load Balancer is created with the specified name, type, security group, and subnets. Deletion protection is enabled.

