### Description
The Terraform configuration provided sets up an AWS Network Load Balancer (NLB) along with a target group and a listener. The NLB is configured to be internet-facing, and the target group uses TCP protocol on port 80. The listener forwards traffic to the target group. The configuration includes a public subnet where the NLB will be deployed. The necessary IAM roles and policies are not explicitly defined in the configuration, but they are assumed to be managed separately.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "network_load_balancer" {
  name               = "my-network-load-balancer"
  internal           = false
  load_balancer_type = "network"
  subnets            = [aws_subnet.public.id]

  enable_deletion_protection = true

  tags = {
    Environment = "production"
  }
}

resource "aws_lb_target_group" "target_group" {
  name     = "my-target-group"
  port     = 80
  protocol = "TCP"
  vpc_id   = aws_subnet.public.vpc_id

  health_check {
    enabled             = true
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Environment = "production"
  }
}

resource "aws_lb_listener" "listener" {
  load_balancer_arn = aws_lb.network_load_balancer.arn
  port              = 80
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.target_group.arn
  }

  tags = {
    Environment = "production"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = "vpc-12345678"  # Replace with your VPC ID
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"

  tags = {
    Name = "PublicSubnet"
  }
}
```

