LLM Output #0:
### Description
This Terraform configuration sets up an Application Load Balancer (ALB) that forwards traffic to one or more EC2 instances in a target group. The configuration includes the creation of the load balancer, target group, listener, and an EC2 instance. The load balancer is configured to listen on port 80 and forward traffic to the target group, which registers the EC2 instance.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "web_sg" {
  name        = "web-sg"
  description = "Allow HTTP traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "load_balancer" {
  name               = "my-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.web_sg.id]
  subnets            = [aws_subnet.public.id]

  tags = {
    Name = "MyALB"
  }
}

resource "aws_lb_target_group" "target_group" {
  name        = "my-target-group"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "instance"

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_lb_listener" "listener" {
  load_balancer_arn = aws_lb.load_balancer.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.target_group.arn
  }
}

resource "aws_instance" "web_server" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for t3.micro instance
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.public.id
  security_groups = [aws_security_group.web_sg.name]

  tags = {
    Name = "WebServer"
  }
}

resource "aws_lb_target_group_attachment" "attachment" {
  target_group_arn = aws_lb_target_group.target_group.arn
  target_id        = aws_instance.web_server.id
  port             = 80
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **VPC and Subnet**: A VPC and a public subnet are created within the VPC.
3. **Security Group**: A security group is created to allow HTTP traffic on port 80 and all outbound traffic.
4. **Load Balancer**: An Application Load Balancer is created with the specified security group and subnet.
5. **Target Group**: A target group is created to register EC2 instances. It includes a health check configuration.
6. **Listener**: A listener is created to forward traffic from port 80 to the target group.
7. **EC2 Instance**: An EC2 instance is launched in the public subnet with the specified security group.
8. **Target Group Attachment**: The EC2 instance is attached to the target group.

This configuration ensures that the load balancer forwards traffic to the EC2 instance, which is registered in the target group.

