### Description
This Terraform configuration sets up an Application Load Balancer (ALB) that forwards traffic to a Network Load Balancer (NLB). The ALB listens on port 80 and forwards traffic to the NLB target group. The NLB then forwards traffic to a backend target group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

# Create public subnets for the Application Load Balancer
resource "aws_subnet" "public_subnet_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  map_public_ip_on_launch = true
}

resource "aws_subnet" "public_subnet_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  map_public_ip_on_launch = true
}

# Create private subnets for the Network Load Balancer
resource "aws_subnet" "private_subnet_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "private_subnet_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.4.0/24"
  availability_zone = "us-west-2b"
}

# Create an Application Load Balancer
resource "aws_lb" "application_load_balancer" {
  name               = "app-alb"
  internal           = false
  load_balancer_type = "application"
  subnets            = [aws_subnet.public_subnet_1.id, aws_subnet.public_subnet_2.id]
  security_groups    = [aws_security_group.alb_sg.id]

  tags = {
    Name = "App ALB"
  }
}

# Create a Security Group for the Application Load Balancer
resource "aws_security_group" "alb_sg" {
  name        = "app-alb-sg"
  description = "Security group for App ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a Target Group for the Network Load Balancer
resource "aws_lb_target_group" "nlb_target_group" {
  name        = "nlb-target-group"
  port        = 443
  protocol    = "TCP"
  vpc_id      = aws_vpc.main.id
  target_type = "instance"

  health_check {
    protocol     = "TCP"
    port         = 443
    interval     = 30
    timeout      = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "NLB Target Group"
  }
}

# Create a Listener for the Application Load Balancer
resource "aws_lb_listener" "application_listener" {
  load_balancer_arn = aws_lb.application_load_balancer.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.nlb_target_group.arn
  }
}

# Create a Network Load Balancer
resource "aws_lb" "network_load_balancer" {
  name               = "net-nlb"
  internal           = true
  load_balancer_type = "network"
  subnets            = [aws_subnet.private_subnet_1.id, aws_subnet.private_subnet_2.id]
  security_groups    = [aws_security_group.nlb_sg.id]

  tags = {
    Name = "Net NLB"
  }
}

# Create a Security Group for the Network Load Balancer
resource "aws_security_group" "nlb_sg" {
  name        = "net-nlb-sg"
  description = "Security group for Net NLB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a Target Group for the Backend Services
resource "aws_lb_target_group" "backend_target_group" {
  name        = "backend-target-group"
  port        = 80
  protocol    = "TCP"
  vpc_id      = aws_vpc.main.id
  target_type = "instance"

  health_check {
    protocol     = "TCP"
    port         = 80
    interval     = 30
    timeout      = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "Backend Target Group"
  }
}

# Create a Listener for the Network Load Balancer
resource "aws_lb_listener" "network_listener" {
  load_balancer_arn = aws_lb.network_load_balancer.arn
  port              = 443
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.backend_target_group.arn
  }
}
```

This configuration creates a VPC with public and private subnets, an Application Load Balancer, a Network Load Balancer, and associated target groups and listeners. The Application Load Balancer forwards traffic to the Network Load Balancer, which then forwards traffic to backend services.

