### Description
This Terraform configuration creates an Application Load Balancer (ALB) with two listeners: one for HTTP traffic on port 80 and another for HTTPS traffic on port 443. The HTTP listener has a rule that redirects all incoming traffic to the HTTPS listener using a 301 redirect.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "load_balancer" {
  name               = "my-alb"
  internal           = false
  load_balancer_type = "application"
  subnets            = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]
  security_groups    = ["sg-0123456789abcdef0"]

  enable_deletion_protection = true

  tags = {
    Environment = "production"
  }
}

resource "aws_lb_listener" "listener_http" {
  load_balancer_arn = aws_lb.load_balancer.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

resource "aws_lb_listener" "listener_https" {
  load_balancer_arn = aws_lb.load_balancer.arn
  port              = "443"
  protocol          = "HTTPS"
  certificate_arn   = "arn:aws:acm:us-west-2:123456789012:certificate/12345678-1234-1234-1234-123456789012"

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "Redirecting to HTTPS"
      status_code  = "200"
    }
  }
}

resource "aws_iam_role" "elb_role" {
  name = "elb-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "elb_policy" {
  name        = "elb-policy"
  description = "Policy for ELB"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:Describe*",
          "ec2:AuthorizeSecurityGroupIngress",
          "ec2:RevokeSecurityGroupIngress"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_elb_policy" {
  policy_arn = aws_iam_policy.elb_policy.arn
  role       = aws_iam_role.elb_role.name
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Load Balancer**: An Application Load Balancer is created with two subnets and a security group. Deletion protection is enabled to prevent accidental deletion.
3. **HTTP Listener**: A listener is created on port 80 that redirects all traffic to the HTTPS listener.
4. **HTTPS Listener**: A listener is created on port 443 with a self-signed certificate ARN. It responds with a fixed message indicating redirection.
5. **IAM Role and Policy**: An IAM role and policy are created for the load balancer, allowing necessary EC2 actions. The policy is attached to the role.

