LLM Output #0:
### Description

This Terraform configuration sets up an Application Load Balancer (ALB) with an HTTP listener on port 80. The listener uses an "authenticate-cognito" action to authenticate users via Amazon Cognito. It also includes a Cognito user pool and a user pool client, as well as an IAM role and policy required for the load balancer to authenticate users.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "front_end" {
  name               = "front-end-alb"
  internal           = false
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id = "subnet-0123456789abcdef0"  # Replace with your subnet ID
  }

  security_groups = ["sg-0123456789abcdef0"]  # Replace with your security group ID

  enable_deletion_protection = true

  tags = {
    Environment = "production"
  }
}

resource "aws_lb_listener" "front_end" {
  load_balancer_arn = aws_lb.front_end.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type = "authenticate-cognito"

    authenticate_cognito {
      user_pool_arn       = aws_cognito_user_pool.pool.arn
      user_pool_client_id = aws_cognito_user_pool_client.client.id
      user_pool_domain    = aws_cognito_user_pool_domain.domain.domain
    }
  }

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.front_end.arn
  }
}

resource "aws_cognito_user_pool" "pool" {
  name = "my-user-pool"

  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  password_policy {
    minimum_length                = 8
    require_lowercase             = true
    require_numbers               = true
    require_symbols               = true
    require_uppercase             = true
    temporary_password_validity_days = 7
  }

  schema {
    attribute_data_type = "String"
    name                = "email"
    required            = true
  }

  schema {
    attribute_data_type = "String"
    name                = "phone_number"
    required            = false
  }
}

resource "aws_cognito_user_pool_client" "client" {
  name            = "my-app-client"
  user_pool_id    = aws_cognito_user_pool.pool.id
  generate_secret = true

  allowed_oauth_flows         = ["code", "implicit"]
  allowed_oauth_scopes        = ["phone", "email", "openid", "profile"]
  callback_urls               = ["https://example.com/callback"]
  default_redirect_uri        = "https://example.com/home"
  logout_urls                 = ["https://example.com/logout"]
  supported_identity_providers = ["COGNITO"]
}

resource "aws_cognito_user_pool_domain" "domain" {
  domain       = "myappdomain"
  user_pool_id = aws_cognito_user_pool.pool.id
}

resource "aws_lb_target_group" "front_end" {
  name     = "front-end-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = "vpc-0123456789abcdef0"  # Replace with your VPC ID

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_iam_role" "lb_auth_role" {
  name = "lb-auth-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "lb_auth_policy" {
  name = "lb-auth-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "cognito-idp:AdminInitiateAuth",
          "cognito-idp:AdminRespondToAuthChallenge"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_lb_auth_policy" {
  policy_arn = aws_iam_policy.lb_auth_policy.arn
  role       = aws_iam_role.lb_auth_role.name
}
```

### Notes

1. **Subnet and Security Group IDs**: Replace `"subnet-0123456789abcdef0"` and `"sg-0123456789abcdef0"` with your actual subnet and security group IDs.
2. **VPC ID**: Replace `"vpc-0123456789abcdef0"` with your actual VPC ID.
3. **Cognito User Pool Domain**: Ensure that the domain name `"myappdomain"` is unique across all existing domains in your AWS account.
4. **Callback URLs and Logout URLs**: Update the callback and logout URLs to match your application's endpoints.

