provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "load_balancer" {
  name               = "my-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = ["sg-0123456789abcdef0"]  # Replace with your security group ID
  subnets            = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1"]  # Replace with your subnet IDs

  enable_deletion_protection = true

  tags = {
    Environment = "production"
  }
}

resource "aws_lb_listener" "listener_443" {
  load_balancer_arn = aws_lb.load_balancer.arn
  port              = "443"
  protocol          = "HTTPS"
  certificate_arn   = "arn:aws:acm:us-west-2:123456789012:certificate/12345678-1234-1234-1234-123456789012"  # Replace with your ACM certificate ARN

  default_action {
    type = "authenticate-oidc"

    authenticate_oidc {
      authorization_endpoint = "https://example.com/authorization_endpoint"
      client_id              = "client_id"
      client_secret          = "client_secret"
      issuer                 = "https://example.com"
      token_endpoint         = "https://example.com/token_endpoint"
      user_info_endpoint     = "https://example.com/user_info_endpoint"
    }
  }
}

resource "aws_lb_listener_rule" "rule_oidc_auth" {
  listener_arn = aws_lb_listener.listener_443.arn
  priority     = 100

  action {
    type = "forward"

    forward {
      target_group {
        arn = "arn:aws:elasticloadbalancing:us-west-2:123456789012:targetgroup/my-target-group/1234567890abcdef"  # Replace with your target group ARN
      }
    }
  }

  condition {
    field  = "host-header"
    values = ["example.com"]
  }
}

resource "aws_iam_role" "oidc_auth_role" {
  name = "oidc-auth-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "oidc_auth_policy" {
  name        = "oidc-auth-policy"
  description = "Policy for OIDC authentication"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_oidc_policy_to_role" {
  policy_arn = aws_iam_policy.oidc_auth_policy.arn
  role       = aws_iam_role.oidc_auth_role.name
}
```

