### Description
This Terraform configuration creates a Network Load Balancer (NLB) with an IP target group. The NLB will distribute incoming traffic to targets registered by their IP addresses. The configuration includes the creation of a VPC, subnets, and the necessary IAM roles and policies to allow the NLB to operate.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

# Create two subnets in different availability zones
resource "aws_subnet" "subnet1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

# Create an IAM role for the NLB
resource "aws_iam_role" "nlb_role" {
  name = "nlb-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
      }
    ]
  })
}

# Attach the necessary policy to the IAM role
resource "aws_iam_role_policy_attachment" "nlb_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonElasticLoadBalancingFullAccess"
  role       = aws_iam_role.nlb_role.name
}

# Create the Network Load Balancer
resource "aws_lb" "load_balancer" {
  name            = "my-nlb"
  internal        = false
  load_balancer_type = "network"
  subnets         = [aws_subnet.subnet1.id, aws_subnet.subnet2.id]
  security_groups = []

  tags = {
    Name = "My NLB"
  }
}

# Create an IP target group
resource "aws_lb_target_group" "ip_target_group" {
  name        = "my-ip-target-group"
  port        = 80
  protocol    = "TCP"
  target_type = "ip"
  vpc_id      = aws_vpc.main.id

  health_check {
    enabled             = true
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
    matcher             = "200-299"
  }

  tags = {
    Name = "My IP Target Group"
  }
}

# Create a listener for the NLB
resource "aws_lb_listener" "listener" {
  load_balancer_arn = aws_lb.load_balancer.arn
  port              = 80
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.ip_target_group.arn
  }

  tags = {
    Name = "My Listener"
  }
}
```

This configuration sets up a basic Network Load Balancer with an IP target group, including the necessary VPC, subnets, and IAM role. The NLB is configured to listen on port 80 and forward traffic to the IP target group.

