### Description
This Terraform configuration sets up an Application Load Balancer (ALB) with a Lambda target group. It includes the necessary IAM roles and policies to allow the Lambda function to be invoked by the load balancer. The configuration also creates a Lambda function and attaches it to the target group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for the Lambda function execution
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# Define the policy for the Lambda function execution role
resource "aws_iam_policy" "lambda_policy" {
  name        = "lambda_policy"
  description = "Policy for Lambda function execution"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the Lambda function execution role
resource "aws_iam_role_policy_attachment" "attach_lambda_policy" {
  policy_arn = aws_iam_policy.lambda_policy.arn
  role       = aws_iam_role.lambda_execution_role.name
}

# Create the Lambda function
resource "aws_lambda_function" "lambda_function" {
  function_name = "lambda_function"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "lambda_function.zip"

  environment {
    variables = {
      LOG_LEVEL = "info"
    }
  }
}

# Create an Application Load Balancer
resource "aws_lb" "lambda_load_balancer" {
  name               = "lambda-load-balancer"
  internal           = false
  load_balancer_type = "application"
  security_groups    = ["sg-0123456789abcdef0"]
  subnets            = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1"]

  tags = {
    Name = "lambda-load-balancer"
  }
}

# Create a target group for the Lambda function
resource "aws_lb_target_group" "lambda_target_group" {
  name        = "lambda-target-group"
  target_type = "lambda"
  vpc_id      = "vpc-0123456789abcdef0"

  health_check {
    enabled             = true
    interval            = 30
    path                = "/"
    port                = "traffic-port"
    protocol            = "HTTP"
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

# Grant permission to the Lambda function to be invoked by the load balancer
resource "aws_lambda_permission" "lambda_permission" {
  statement_id  = "AllowExecutionFromLoadBalancer"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.lambda_function.function_name
  principal     = "elasticloadbalancing.amazonaws.com"
  source_arn    = aws_lb.lambda_load_balancer.arn
}

# Create a listener for the load balancer to forward traffic to the target group
resource "aws_lb_listener" "lambda_listener" {
  load_balancer_arn = aws_lb.lambda_load_balancer.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.lambda_target_group.arn
  }
}
```

### Explanation
1. **Provider Configuration**: Sets the AWS region to `us-west-2`.
2. **IAM Role and Policy**: Creates an IAM role for the Lambda function and attaches a policy that allows the function to write logs to CloudWatch.
3. **Lambda Function**: Defines a Lambda function with a simple handler and runtime.
4. **Application Load Balancer**: Creates an ALB with specified security groups and subnets.
5. **Lambda Target Group**: Creates a target group for the Lambda function with health check settings.
6. **Lambda Permission**: Grants the ALB permission to invoke the Lambda function.
7. **Listener**: Sets up a listener on the ALB to forward HTTP traffic to the Lambda target group.

