### Description

This Terraform configuration creates an AWS RDS database instance with storage autoscaling enabled. It includes the necessary IAM roles and policies, parameter groups, and option groups to support the autoscaling functionality. The configuration ensures that the database instance can dynamically adjust its storage capacity based on demand.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for RDS Autoscaling
resource "aws_iam_role" "rds_autoscaling_role" {
  name = "rds-autoscaling-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "application-autoscaling.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for RDS Autoscaling
resource "aws_iam_policy" "rds_autoscaling_policy" {
  name        = "rds-autoscaling-policy"
  description = "Policy for RDS Autoscaling"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "rds:DescribeDBInstances",
          "rds:DescribeDBClusters",
          "rds:DescribePendingMaintenanceActions",
          "rds:ApplyPendingMaintenanceAction",
          "rds:ModifyDBInstance",
          "rds:ModifyDBCluster",
          "cloudwatch:PutMetricAlarm",
          "cloudwatch:DescribeAlarms",
          "cloudwatch:DeleteAlarms",
          "cloudwatch:EnableAlarmActions",
          "cloudwatch:DisableAlarmActions"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_rds_autoscaling_policy" {
  policy_arn = aws_iam_policy.rds_autoscaling_policy.arn
  role       = aws_iam_role.rds_autoscaling_role.name
}

# Parameter Group for enabling storage autoscaling
resource "aws_db_parameter_group" "db_parameter_group" {
  name   = "db-parameter-group"
  family = "mysql8.0"

  parameter {
    name  = "max_allowed_packet"
    value = "1073741824"
  }
}

# Option Group for enabling storage autoscaling
resource "aws_db_option_group" "db_option_group" {
  name         = "db-option-group"
  engine_name  = "mysql"
  major_engine_version = "8.0"
}

# RDS Database Instance
resource "aws_db_instance" "database_instance" {
  instance_class = "db.t3.micro"
  allocated_storage    = 20
  max_allocated_storage = 100
  engine               = "mysql"
  engine_version       = "8.0"
  username             = "admin"
  password             = "password"
  parameter_group_name = aws_db_parameter_group.db_parameter_group.name
  option_group_name    = aws_db_option_group.db_option_group.name
  storage_type         = "gp2"
}

# AppAutoscaling Target for Database Storage
resource "aws_appautoscaling_target" "db_storage_autoscaling_target" {
  service_namespace = "rds"
  resource_id       = "db:mysql:${aws_db_instance.database_instance.identifier}"
  scalable_dimension  = "rds:db-instance:AllocatedStorage"
  min_capacity      = 20
  max_capacity      = 100
  role_arn          = aws_iam_role.rds_autoscaling_role.arn
}

# AppAutoscaling Policy for Database Storage
resource "aws_appautoscaling_policy" "db_storage_autoscaling_policy" {
  name                = "db-storage-autoscaling-policy"
  service_namespace   = "rds"
  resource_id         = aws_appautoscaling_target.db_storage_autoscaling_target.resource_id
  scalable_dimension  = "rds:db-instance:AllocatedStorage"
  policy_type         = "TargetTrackingScaling"

  target_tracking_scaling_policy_configuration {
    predefined_metric_specification {
      predefined_metric_type = "RDSReadReplicaLatency"
    }
    target_value = 100.0
  }
}
```

This Terraform configuration sets up an RDS MySQL database instance with storage autoscaling enabled. It includes the necessary IAM roles and policies, parameter groups, and option groups to support the autoscaling functionality. The database instance is configured to dynamically adjust its storage capacity between 20 GB and 100 GB based on the specified target tracking policy.

