### Description
This Terraform configuration sets up a dedicated-tenancy AWS VPC with DNS support and hostnames enabled, an internet gateway, and a route table for outbound internet access. All resources are tagged with a variable name provided during deployment.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify the desired AWS region
}

variable "vpc_name" {
  description = "Name to tag the VPC, internet gateway, route table, and route"
  default     = "dedicated-tenancy-vpc"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

resource "aws_vpc" "dedicated_tenancy_vpc" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true
  instance_tenancy     = "dedicated"

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "internet_gateway" {
  vpc_id = aws_vpc.dedicated_tenancy_vpc.id

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_route_table" "route_table" {
  vpc_id = aws_vpc.dedicated_tenancy_vpc.id

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_route" "route_to_internet_gateway" {
  route_table_id         = aws_route_table.route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.internet_gateway.id
}

resource "aws_default_security_group" "default_security_group" {
  vpc_id = aws_vpc.dedicated_tenancy_vpc.id

  tags = {
    Name = var.vpc_name
  }
}
```

This configuration creates a VPC with the specified CIDR block, enables DNS support and hostnames, and sets the instance tenancy to dedicated. It also creates an internet gateway, a route table, and a route to allow outbound internet access. All resources are tagged with the provided `vpc_name` variable.

