### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "vpc_name" {
  description = "Name to tag the VPC, internet gateway, route table, and default security group"
  default     = "dedicated-tenancy-vpc"
}

resource "aws_vpc" "dedicated_tenancy_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  instance_tenancy     = "dedicated"

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "internet_gateway" {
  vpc_id = aws_vpc.dedicated_tenancy_vpc.id

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_route_table" "route_table" {
  vpc_id = aws_vpc.dedicated_tenancy_vpc.id

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_route" "route_to_internet" {
  route_table_id         = aws_route_table.route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.internet_gateway.id
}

resource "aws_default_security_group" "default_security_group" {
  vpc_id = aws_vpc.dedicated_tenancy_vpc.id

