  assign_generated_ipv6_cidr_block = true

  tags = {
    Name = "vpc-for-egress"
  }
}

resource "aws_egress_only_internet_gateway" "egress_only_internet_gateway_pike" {
  vpc_id = aws_vpc.vpc_for_egress.id

  tags = {
    Name        = "pike"
    permissions = var.permissions_tag_value
  }
}
