### Description
This Terraform configuration creates a NAT Gateway associated with a specified subnet and Elastic IP allocation ID. The NAT Gateway is configured for public connectivity. The configuration includes the creation of an Elastic IP, a NAT Gateway, and an Internet Gateway to ensure proper routing.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "main-vpc"
  }
}

# Create an Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

# Create a Subnet
resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet"
  }
}

# Create an Elastic IP
resource "aws_eip" "nat_gateway_eip" {
  vpc = true

  tags = {
    Name = "nat-gateway-eip"
  }
}

# Create a NAT Gateway
resource "aws_nat_gateway" "nat_gateway" {
  allocation_id = aws_eip.nat_gateway_eip.allocation_id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "nat-gateway"
  }

  # Ensure proper ordering, it is recommended to add an explicit dependency
  # on the Internet Gateway for the VPC.
  depends_on = [aws_internet_gateway.igw]
}
```

This configuration sets up a basic VPC with an Internet Gateway, a public subnet, an Elastic IP, and a NAT Gateway. The NAT Gateway is associated with the public subnet and the Elastic IP, ensuring that instances in the subnet can access the internet.

